    "promptTemplate": "将提供的内容表现为有复古温度的二维科幻动画。主体轮廓清楚，场景像经过耐心绘制的电影美术，保留旧物质感和真实生活尺度。机械结构可以拥有情绪，但情绪主要通过目光、姿态和行为出现，不要求复制原作机器人、信件或送达旅程。用户的题材和事件保持自主，画面用手绘线条、有限色阶与克制的光色建立统一风格。\n\n角色由少量易辨认的几何体组成，大块外壳与细长连接部件形成比例节奏。转轴、关节、手指和脚部保持实际连接，关节只在合理范围活动。外壳边缘略有磨损，接缝与小螺钉适量出现，细节位置固定，不用密集机械纹样覆盖整个身体。若角色有屏幕或图形式面部，使用简单的眼睛位置、眼睑和表情线来表达，面部始终属于同一平面或曲面，不突然长出真实皮肤与嘴唇。\n\n绘制方式保留清晰但不死板的深色轮廓，结构交叠处线条较明确，受光边缘可以适当减弱。阴影以经过设计的色块分区，再加入少量柔和环境渐变，避免全局三维塑料高光。金属呈现旧漆、轻微划痕与暗淡反射，纸张有厚薄边缘，木材和墙面用有限笔触说明纹理。画面允许细小绘画颗粒，颗粒依附表面，不每一帧随机重新排列。\n\n配色采用灰蓝、墨青、锈红、赭褐和奶油色，主角与环境有明确但柔和的色差。暖黄或琥珀光可以作为注意力中心，但必须照亮相邻表面，并随距离减弱；夜景的深蓝与室内暖光有清楚边界，白天则保留轻盈空气和较浅的阴影。亮处仍能读出轮廓，暗处不全部涂黑。科幻感来自结构、使用方式与空间想象，不依赖满屏霓虹和发光电路。\n\n场景绘制兼顾生活痕迹和构图秩序。管道、街道、建筑或家具按用户地点组织，前景有遮挡，中景有行动路径，远景用较少线条和更低对比延伸。透视可具有手绘的柔性，但地面、门窗与主体尺度保持一致。普通杂物只放在有功能的位置，既提供生活感，也留出让角色移动和表达的空处。经过玻璃、门洞或其他遮挡后，物体应保持原来的结构和位置。\n\n动作有机械的逻辑，也有生命的停顿。视线先注意某个目标，头部或外壳随后倾斜，身体重心再转移；步行时脚部接触明确，关节依次折转，手部抓握后与对象维持稳定连接。情绪可通过肩部收紧、身体微倾、手指犹豫或短暂静止表达，避免持续弹跳卖萌。硬外壳不挤压成橡胶，软连接与携带物可以有有限滞后。快速动作保留清楚的方向和落点，机械部件不凭空增删。\n\n摄影维持二维动画的设计感与电影空间感。选择能读清轮廓和动作的观察距离，移动时让前后层产生适度视差，不把场景简单拖动成背景板。焦点和光色变化服务用户事件，剪辑衔接视线、行动方向及环境状态，不预设固定镜头顺序。跨帧保持线条粗细、外壳色块、关节数、屏幕比例和旧漆磨损位置，动作带来姿态变化而不是角色重绘；全段维持温暖、清晰且具有实体触感的手绘科幻世界。",
