    "promptTemplate": "把用户提供的内容转化为具有雕塑感和温柔光色的三维奇幻动画。保留原有角色、事件和世界设定，通过紧凑而有辨识度的造型、能触摸的材质与清楚的表演建立亲近感。梦幻感来自空间层次和光的相互作用，奇观始终由具体动作触发，整段像一个被认真设计和照顾过的小世界。\n\n角色先有清楚的头身比例、外轮廓和重心。轮廓可用圆角、卷曲、短粗与细长的对照概括，脸部保留足够空间表达视线和情绪。眼睛有稳定的眼眶与转动方向，口型、眉部和头部倾斜共同参与表演，不能只让眼睛一味放大。衣服、发型与随身物件的轮廓能从不同角度识别，装饰有具体作用，避免直接复制参考作品的白卷发与眼镜组合。\n\n材质至少分出柔软、纤维、硬质与透明的触感。布料有细小织纹和受力褶皱，蓬松结构由大小不均的团块形成，外缘柔而内部仍有层次；金属和漆面保留克制的反射，木材、石材或工具表面有细小使用痕迹。发光物也具有厚度、容器接触和黏度，高亮区域保留颜色，不能变成没有边界的白色光斑。\n\n光色以统一的环境基调组织，蓝紫、青色或其他适合内容的低亮度色域托住温暖面部与局部光源。来自窗、灯、液体或天空的光有明确方向，能照亮邻近衣物、手部和器物边缘。暗处保留柔和反射，亮暗过渡宽而清楚；远处降低饱和度和细节，近处适度提高色彩纯度，让环境既有梦幻色泽，又保持可辨的形体深度。\n\n场景如精心搭建的立体故事空间，有可走动的地面、可触碰的工具和前后分明的环境层。柔软地貌、悬浮结构或奇幻尺度都可以出现，但人物站立时有压迫、遮挡与阴影。室内细节围绕角色习惯排列，外部空间用大形和空气留白展开。不要让每个角落都堆满发光装饰，关键动作周围保持清爽的视觉通道。\n\n动作遵循观察、准备、执行和反应的连续关系。拿起物件时先看向目标，再伸手接触，握持位置固定，物件的重量影响手臂和身体；转身由腰腹带动，衣角和柔软附属结构随后跟进。惊讶、犹豫和喜悦通过姿态的张开或收拢表达。快速动作之后有短暂回收，安静时仍保持自然呼吸与视线变化，避免全程匀速缓慢漂浮。\n\n奇幻效果从行为接触点产生，沿已经建立的方向扩展。涂抹有笔迹起落，粒子有产生、飞行和消散，光亮会在物体移动后改变位置。镜头靠近时看清手部和材质，退远时让人物与环境的尺度关系成立；切换视角保持视线、动作方向和物件状态。跨帧固定角色比例、卷曲或纹理分布、服装连接、道具数量与照明逻辑，保持表情细节和环境布局连续，让柔软童话也具有可靠的动作因果。",
