    "promptTemplate": "把用户给定的内容转化为具有纸塑木偶与微缩剧场气质的动画，建立一套可触摸、可表演的材料世界。保留人物、物品与事件的原有功能，角色可以是人形、动物或抽象生命，但造型要经过概括：偏大的头、清楚的鼻部与眼窝、略不对称的脸面，配合适量夸张的手脚。避免真人皮肤和塑胶公仔的均匀光滑，让面孔像纸浆、木雕或有压痕的陶土制作，保留细小褶皱、接缝、擦色和手工成形的凹凸。这些痕迹应附着在固定位置，转头时随形体转动。\n\n服装使用可辨认的粗毛线、棉布、旧皮革等材料。织物有针脚方向与边缘厚度，身体弯曲时在合适位置堆起褶皱；头发可以是成束纤维，眼镜、纽扣与道具是有重量的小零件。让不同材料在画面里彼此衬托，不把所有表面都处理成毛毡。小生物可以混合绒毛、纸片、木质或细绳，但每一个造型内部的材料逻辑一致，避免随意长出无关器官。\n\n环境像精心布置的舞台模型。墙板、窗框、地板和门具有略粗的纹理与边缘磨损；植物以折叠、切片、卷曲和层叠构成，前中后景错开距离。空间需要足够让身体站立和移动，不能只是扁平装饰。综合色以低饱和的青绿、木棕、苔绿和米色为基础，用柔和粉红、紫色或暖黄作为局部惊喜。可见光源或合理的窗光制造温暖亮区，暗部保留材料细节，空气稍有柔化但不产生厚重滤镜。把亮度重点交给表情、手部和互动对象。\n\n表演带有木偶的克制与重量。角色先通过目光和头部倾斜确认对象，身体稍后跟进；手指接近物件时建立接触，再带动物件的位置。步行中的脚掌明确落地，身体轻微摇摆，衣服和纤维产生较慢的附随运动。允许关键姿势间有轻微顿挫，形成手工动画般的节奏，但镜头不能因为追求定格感而随机丢帧或抖动。情绪可以通过长短不一的停顿、抬眉、收肩、握紧和松手呈现，避免不停张嘴和全身晃动。\n\n若内容适合想象性变化，可让大与小、内部与外部的空间发生巧妙联系，例如日常物件变成可进入的场所，或同一个角色的不同状态以小型化造型出现。变化要有视觉动机与稳定的尺度参照，不强制复制原作的人物或寓言。摄影像观察一座活起来的模型，可以缓缓接近表情、沿布景横移，或让前景叶片经过镜头形成遮挡。景深支持观看重点，不能把全部背景虚化得失去手工层次。跨画面维持脸型、材质、服装织纹、关节位置与物体尺寸，动作发生后保留它留下的结果，让每一次奇想都仍然落在可信的小世界里。",
    "negativePrompt": "避免真人毛孔、蜡像人脸、塑料玩具统一高光、所有材料毛毡化、纸纹漂移、针织纹反复重生、玻璃眼珠过大、玩偶嘴部无休止开合、漂浮脚掌、布景随镜头重构、无支点弯曲、关节数量变化、尺度无参照跳变、假定格随机卡顿、景深把环境完全抹掉、廉价儿童玩具广告质感。",
