    "promptTemplate": "将用户内容表现为精心搭建的微缩童话动画，兼有清楚的三维体积、轻微的手工痕迹与定格动画般的姿态节奏。人物和事件由用户内容决定，不预设儿童、衣柜或平行世界情节。角色的头部、鼻子、耳朵和手掌可以适度概括，眼神与眉形明确，面部像精细塑形的小模型，保留柔软而不油亮的表面。头发组织为有方向的发束，衣物具有真实厚度和细小织纹；角色的主要轮廓要足够简洁，使近处表情和远处姿势都能被读懂。\n\n场景中的材料各司其职。纸板保留切口与折痕，木家具带方向性的纹路和边缘磨损，布料有缝线、编织与轻微褶皱，金属小零件以局部反光说明硬度。细节集中在常被触碰和有功能的位置，不把所有表面加上同一种做旧纹理。房间、街道或其他空间像真实存在的模型，门窗能开合，抽屉和道具有厚度，地面能承受人物重量。根据内容安排少量使用痕迹和生活物件，让环境有主人，而不是整齐陈列的玩具商店。\n\n综合色大胆但有层次。可以让蓝、绿、木棕或其他主色统领空间，暖光照亮活动区域，暗处保留可辨认的几何结构。窗光、台灯或自发光对象都要在附近材料上留下对应光色，不能靠统一光晕表达温暖。近处表面清晰，远处有适量景深和空气柔化，仍能读出房间的功能关系。如果内容需要幻想，把熟悉形状有计划地改造成曲线家具、植物般构件或有生命感的物件；以相似的功能与位置作为观看线索，避免杂乱堆积眼睛、触手和发光装饰。\n\n角色行为以小而明确的动作建立情感。注意力先通过眼神和头部方向变化，再传递到肩膀、手和脚；打开、拿起、靠近或退开都有明确接触与重心变化。对陌生事物的反应可以包含短暂僵住、试探前倾、收手和重新接近，停顿让观众读出想法。较活跃的动作保留短促的关键姿势与清楚余势，布料、发束和小道具稍后跟动。不要让身体一直弹跳，也不要用随机卡顿模拟手工拍摄。动物或幻想生物同样需要稳定的运动方式，毛发、耳朵和尾巴只在行为需要时回应。\n\n摄影维持微缩空间的亲近感。通过门框、家具边缘或前景物件形成层次，让角色进入和离开可见区域，利用视线与遮挡自然产生好奇。观察距离的变化服务于发现、回应或空间揭示，镜头可以稳定等待，再随动作有目的地移动，避免一直绕着人物炫示场景。若两个空间彼此对应，可用相似构图、角色姿态或道具功能建立联系，再逐渐显出材料和色彩差异，不强制使用分屏或传送门。跨帧保留五官比例、衣纹、物体数量、家具位置和影子方向，已被挪动的物件维持新位置，让奇异世界仍遵循可理解的物理和表演逻辑。",
