    "promptTemplate": "把用户的内容转化为有鲜明表演节奏的表现主义动画，让形状、笔触和综合色参与角色的情绪表达。人物、物品及事件保留用户的设定，整体使用经过设计的二维轮廓与绘画表面。角色比例可以被概括和推高，头部、眼睛、发束、手掌或重要道具形成容易记住的大形；五官少而有表现力，服饰以清楚的色块区分。不同视角下可以为了轮廓可读性微调造型，但身份特征、色区和基本身体关系必须延续，不能换脸或随意增减结构。\n\n表面采用厚薄并存的干笔刷、粗颗粒擦痕、叠涂色块与少量铅笔般的轮廓线。笔触沿头发走势、衣物转折、木板方向或环境的大面组织，局部保留露底与不规则边缘。细节应像画者一次次落笔形成，而不是贴在画面上的统一噪点。质感在静止时可有克制的手绘跳动，形体的边界、眼神和手指保持明确。将空间概括成有角度的家具、倾斜的线条与相互遮挡的色面，保留人物能站立、接触和穿行的稳定区域。\n\n综合色从内容的情绪出发。安静、犹豫或沉思时，可以使用深蓝、灰紫与偏冷的浅色，靠局部暖光和明度差分离角色；紧张或兴奋时，允许青绿、洋红、橙黄逐渐侵入画面。颜色变化应有情绪或动作的起因，先改变重点部位，再带动周边环境。灯光仍要说明前后关系和接触位置，但不要把绘画表面做成精细写实的三维皮肤。最强烈的表达可以简化背景，让轮廓、色块与负空间承担情绪，而不是用眩光覆盖人物。\n\n动作以可读的姿势和对比节奏为核心。先让观众理解注意力与受力方向，再通过肩颈、手部、躯干和重心的变化展开行为。小动作保留眼神先行、短暂迟疑及轻微错拍；大动作可以延长肢体的弧线、压缩躯干或拉开表情，但每次变形都要经过连续的过渡，并回到稳定造型。停顿是表演的一部分，不能所有部位一直摇动。情绪高点可让外部色块沿运动方向拉伸、碰撞或迸发，以重复形状形成重音；没有相应情绪或事件时，保持简洁，不强迫角色愤怒或经历幻觉。\n\n摄影围绕行为组织视线，观察距离应让关键姿势被读懂。靠近时强调目光、呼吸和手部细节，拉远时让肢体方向与环境几何相互呼应。镜头的启动和停止与动作节拍配合，可用短暂稳定衬托突然变化，不能持续漂浮旋转。若需要剪辑，以姿势、运动方向或色彩重心形成联系，允许表现主义空间转换，但保持人物所在的叙事关系。跨帧维持眼睛数量、发型标志、服装分区、道具握持与前后遮挡，笔触变化服从动作，不让背景纹理代替角色表演。",
    "negativePrompt": "避免写实毛孔、塑料皮肤、平均铺满的油画滤镜、无方向噪点、笔触覆盖五官、全身持续抖动、无动机色温跳变、手指随机增减、眼睛漂移、肢体无原因拉长、轮廓每帧重画成另一人、无回收的橡胶变形、全屏眩光、镜头不停绕行、把情绪统一做成愤怒。",
