    "promptTemplate": "把用户内容制作成具有电影空间感的三维动画，让简洁可爱的主体与有分量的材料、环境和动作形成鲜明对照。角色可以使用圆形、卵形或其他整体感强的体积，保留用户需要的身份和功能，不强制变成蛋或武士。轮廓优先，脸部由少量清楚的眉、眼、口组成，肢体比例可以较短，但必须有明确连接和稳定支点。主表面保持温润、细腻、略带粗糙度，光照下呈现完整曲面，不添加过密皮肤细节，也不要像充气玩具般高亮。\n\n服装与装备承担材料层次。棉麻、皮革、编绳、毛束和磨旧金属按照功能组合，边缘有厚度、接缝有位置，局部磨损围绕经常接触和受力的区域分布。保留主体干净的大形，让高密度细节集中在衣领、腰带、手部或关键道具。衣物应包裹角色的圆体而不是穿进身体；转身或弯腰时褶皱有所变化，但花纹、绑带和装备数量保持固定。不同角色用轮廓、配色和动作习惯区分，而不是只换一个表情。\n\n环境拥有真实尺度下的材质与深度，再进行适度美术化。木材、岩石、苔藓、织物与水流都能看出各自的粗糙度和反光方式，前景适量放置遮挡物，远景通过空气和细节减弱拉开距离。小角色在宽阔场景中仍有清楚的受光面。日光可从侧上方扫过圆形轮廓，带出柔软亮缘与接触阴影；阴影偏冷，受光处偏暖，避免无处不在的金色光晕。复杂场景先保留大块综合色，不让树叶、石头与水花平均争夺注意力。\n\n动作要让可爱造型具有可信的重量。人物发现状况时先用眉眼和头部方向说明注意力，再通过重心变化展开跑动、躲闪、抓握或协作。短肢角色可以迈小步、快速调整平衡，也可以在失衡后靠全身转动恢复姿态，喜剧来自身体与任务之间的反差。跳跃前有蓄力，落地后有短暂压缩与回弹；转向时身体和随身物件呈现不同的惯性。不要把每次失误都做成无重力弹跳。多人共同操作物件时，动作方向与受力一致，物件的运动必须回应接触位置。\n\n自然运动围绕角色行为发生。脚步带起少量尘土，衣角和毛束延迟摆动，流水推动船体后才引发角色重新站稳，飞溅和落叶说明运动路径而不遮盖主体。摄影可以贴近小角色的高度，利用广阔环境衬托挑战；追随动作时保持主要方向可读，靠近表情时保留脸部轮廓与眼神。需要切换观看距离时，让落点、目标和空间关系能够接续。节奏包含观察、准备、行动与余势的差异，不能全程高速或全程慢放。跨帧稳定角色体积、五官位置、服装分区、道具尺寸和环境结构，用清楚的动作因果串起用户自己的事件，而不是固定一套冒险情节。",
