    "promptTemplate": "将用户提供的内容表现为自然材料塑成的精细木偶动画。保留原有故事、角色和场景，造型像由石块、泥土、树皮、纤维或植物组织手工构成，材质本身参与角色性格与动作。整体亲近、安静而富有情绪，具有微缩实景的光影和定格动画的节奏，不将自然风格理解为静态风景展示。\n\n设计先区分主体的重量与柔韧性。厚重形体由较大的块面和明确接缝组成，头部与躯干有稳定连接，手部和肢体在结构允许的范围活动；纤细形体可以通过叶脉、茎秆、薄片或轻软纤维构成，关节不必写实，却要可读。面部与材料融为一体，眉眼和口部能表达观察、迟疑与回应，避免在普通石头上直接贴一张人脸。\n\n石材保有颗粒、裂缝和磨损，泥土显出干湿差异，树皮沿生长方向开裂，苔藓由柔软而有密度变化的细簇构成。透明或半透明部件内部有浑浊、气泡或细小杂质，受光时呈现厚度。纤细绒毛和种子冠毛保持根部附着，数量与分布稳定；角色运动时材料随身体而动，不能让苔藓持续重新长出或将石块变成流体。\n\n配色取自土褐、灰绿、深木色、枯叶黄等自然综合色阶，少量暖金或内容指定的强调色聚焦情绪。阳光从树隙、窗边或场景中可理解的方向进入，近处投下有形状的柔影，远处逐步降低对比。夜景可以用冷蓝空气承托局部暖光，但发光物仍具有可辨外形，不将整片环境染成均匀荧光。湿润表面反光细碎，干燥材质保持哑光。\n\n空间围绕角色尺度组织，让普通纹理显得像可以攀爬和触摸的地貌。地面、树根、桌面或其他支撑物都有起伏与接触关系，前景遮挡建立纵深，背景细节轻柔退去。环境的变化应当有连续原因：风经过时先后影响不同层次，水滴落下后留下湿痕，光线移动也保留既有方向。不要在每次切镜时重新排列同一场景。\n\n动作细致而克制，先通过视线和身体倾向表达意图，再发生接触和移动。厚重角色启动稍慢，落地和握持有重量；轻盈角色的动作较敏捷，末端纤维延迟摆动后逐渐安静。表情通过眨眼、眉部压低、微小转头和停顿形成层次，不需要持续夸张口型。可以有手工定格般的轻微节奏颗粒，但动作路径仍连续，不能把跳帧错位当作风格。\n\n摄影贴近角色高度，观察材料和表演之间的关系。较近视角突出眼神、手部与触碰，较远位置交代人物与环境的距离；运动缓急由情绪和行动带动，留出反应与结果的时间。跨帧固定裂缝、苔藓、叶片连接、身体比例及照明关系，季节或状态变化要有渐进过程与清楚结果。让自然材料呈现可感知的生命、重量和记忆，而不是让画面始终漂浮在空泛的梦境里。",
    "negativePrompt": "避免参考石偶与蒲公英角色原样复制、石头橡胶化、苔藓逐帧沸腾、植物四肢无因增生、冠毛随机消失、表情贴在材质上、过度光滑塑料面孔、全屏精灵光点、浅景深遮蔽动作、脚部无接触阴影、环境纹理游走、只做静图缩放。",
