    "promptTemplate": "将用户内容转化为手工纸板木偶气质的角色喜剧动画。人物和物件保持用户设定，以简单、可辨的几何大形承担表演，材料显得由人亲手切割、粘合和装配过。整体具有微缩实景的空间可信度与动画的夸张节奏，幽默来自角色面对事件时的姿态、反应与动作因果，不依靠随机变形或满屏表情符号。\n\n造型由硬质主体、柔性连接和少量独立表情部件组成。大形可以方、圆、扁或不对称，连接点和支撑方式必须稳定；眼睛、眉部与嘴部在有限范围内运动，让视线方向和情绪清晰。细长四肢可以像弯折毛根、软绳或铰链，但不同材料遵守不同弯曲方式。装饰简洁且有功能，避免直接套用参考作品的芯片外形和品牌标记。\n\n保留纸面纤维、切口厚度、涂色笔触、拼接线与轻微不平整。硬纸板在转身时整体转动，边缘不会像橡皮一样塌陷；毛根有细短绒毛和弯折记忆，金属、木头、布料等道具则各自保有对应的反光和粗糙度。局部允许手工装配的偏差，但不能让每帧的缺口、花纹和粘接位置重新生成。特写要看见触感，也要给表情留出干净区域。\n\n照明像为小型布景认真布光：温暖生活空间拥有柔和主光与局部灯具，冷色机械环境有方向明确的顶光和反射。角色靠近墙面、桌面或其他物件时出现接触阴影，亮部不过分光滑，暗部保留纸板和毛根的层次。颜色用较中性的木色、灰色和低饱和环境承托少量鲜明角色色，避免全部道具同时抢眼。\n\n空间具有真实可行动的尺寸关系。门、桌、楼梯、工具与角色相互适配，前景遮挡和适度景深强调微缩感，而不是将远处全部虚化成色斑。背景可以细致但布置有秩序，关键交互区域清楚可见。物体被拿起、推动或放下后维持新位置；环境对动作产生合理反馈，地板、弹性垫或绳索不会只作平面装饰。\n\n表演以明确目标和身体重心为核心。角色先察觉事件，再转眼、停顿、改变姿态，随后执行动作；预备时压低或后倾，发力时整个硬壳随重心移动，落点有缓冲与回收。柔软四肢稍晚跟随，硬壳本身避免无因拉伸。喜剧可以使用尴尬停顿、过度认真或努力后的失衡，动作的起点、峰值和后果都要让观众读清。\n\n摄影采用角色视线附近的观察位置，必要时降低机位强调小角色面对大空间的压力。跟随运动时有适度启动和制动，切镜围绕动作完成点与反应组织，镜头不持续晃动掩盖细节。跨帧固定角色比例、眼睛位置、纸面纹理和布景布局，允许操偶般的微小不完美，但不出现身体身份漂移。整体保有手工触感、清楚的动画表演和经过编排的喜剧节奏。",
