    "promptTemplate": "用精细的二维漫画动画呈现用户指定的内容，在明确线稿与柔和光色之间建立平衡。人物的身份、年龄表达和服装遵循用户设定，不自动套用原片的故事或外貌。造型以稳定的头部比例、发束结构、眼形和配饰建立识别度。五官可以适度美化，但保留性格差异，眼睫、眉线和口部边缘细而明确，表情来自形状变化而不是机械贴换一张脸。人物的身体比例与环境尺度保持一致，不让精致头像和粗略身体脱节。\n\n上色以清楚的大色块为基础，面部和衣物转折使用少量可读的赛璐璐阴影，再用克制的软边渐层表现脸颊、鼻尖和环境反光。虹膜可以有细小颜色层次与单纯高光，眼白不能亮得脱离场景。头发按成束结构产生亮暗，不逐根追求摄影质感。近景允许少量雀斑、线痕或服装细节，纹理必须贴着形体稳定存在。保留绘画感，避免把嘴唇、鼻子和皮肤做成与线稿不相容的真实人体局部。\n\n环境具有生活空间的结构感。窗框、墙面、家具、街道与建筑先给出明确透视和遮挡，再用综合色营造气氛。柔和场景可以使用灰粉、浅紫、暖白与低饱和绿色；夜间或情绪紧张时，可以用深蓝、暗紫和红光建立更锐利的色域对比。光源应改变人物受光面与阴影方向，不能只叠加一层彩色滤镜。轮廓光、反射和光晕只强调视觉重点，不盖住线条。若用户内容包含幻想，允许空间和角色被图形化、符号化或非人化，但它们应继承同一套线条精度和综合色关系，而非突然切换到另一种渲染体系。\n\n人物表演注重细微的注意力转移。让眼神先找到目标，再带动眉眼、下颌、肩膀和身体方向；说话的口型与停顿有自然间隔，听者保留反应，不把所有角色都做成不停眨眼的立绘。情绪较强时，姿势可更加明确，重心前移、手部收紧或身体退让应有连续的起因与结果。走动、转身和奔跑要让脚部接触地面，服饰和头发的滞后服从惯性。允许动画式的姿势强调，但不要牺牲关节和空间逻辑。\n\n摄影靠观看距离与视线关系组织叙事。近处观察表情和手势，中远距离展示人物与城市或室内的关系；镜头移动要回应角色注意力或空间揭示，不用持续推近冒充情绪发展。剪辑时延续目光方向、人物站位和色彩重心，动作的前后状态要能接得上。日常与幻想之间的变化可以通过相似形状、光线或姿势衔接，并保持角色的基本特征。跨帧固定眼睛、发型、衣领和配饰的位置关系，控制嘴型、手指与图案的连续性，让细密美术成为可信表演的支撑，而不是掩盖运动不足的装饰。",
    "negativePrompt": "避免真人皮肤毛孔、三维偶像塑胶脸、过量唇部反光、瞳孔游移、左右眼换色、眼睫闪烁、嘴型永远张开、立绘反复推拉、全身仅有头发飘动、发型每镜变化、手指合并、衣领图案重生、无动机强光闪烁、情绪全部靠滤镜变色、幻想段落随机换画风、预设原片人物身份与故事。",
