    "promptTemplate": "把提供的内容组织为有深夜呼吸感的绘本动画。世界具有可行走的空间和可信的重力，表面却保留粉彩、干刷与纸上颜料的触感。用一个容易辨认的主体与较大的环境建立观看关系，让情绪来自它如何观察、犹豫和行动。题材依照用户内容展开，不自动加入原作的鸟、绿石或特定旅程，也不要求把每个故事都放到海边。\n\n造型先抓住清楚的大轮廓，再铺设有方向的内部纹理。动物或人物可以略微圆润，眼睛、鼻口和关节保持简洁；物件则保留其用途和基本构造。羽毛、毛发、树皮和岩层用成组短线与色块表现，纹理顺着体积转折，边缘适度柔化。近景有细节，中远景主动减少笔触，避免整幅均匀锐利。结构坚实但不僵硬，不把主角的表情依赖于夸张嘴形或人类眉毛。\n\n以靛蓝、石油蓝、深青和墨绿建立大面积暗色，用温暖棕褐、灰白或局部浅色区分主体。若内容需要光辉，让它表现为清楚的色带、薄雾透光或有限的发光物，不用全屏荧光点装饰。夜色中仍有明暗层次：近处遮挡深，远处空气较亮，受光轮廓有柔软过渡。材质之间保持差异，水面带横向节奏，岩石吸光，柔软身体有温和的反射，不将所有表面刷成同一种油亮质感。\n\n场景构成采用近处轮廓、中景行动与远处开阔空间的关系。树干、洞口或岸石可以形成自然框景，但给主体保留能够进入和离开的路径。天空、山体与水面以稳定大色块相互衬托，细小星点和草叶只在需要处出现。远景具有绘画的平面概括，也保持透视、遮挡和尺度一致；镜头运动时各层的位移不同，不能像整张插画一起滑动。\n\n表演清晰、轻微而有想法。视线先捕捉刺激，头部随后转向，身体再决定是否移动；停顿期间允许短促眨眼或小幅重心调整，不让每个部位持续晃动。步行要有落脚、承重和离地，较圆的躯干随重心轻微起伏，附属结构有适度滞后。不同生物保留不同的运动逻辑，巨大形体的转向更缓，细小物体可以敏捷。环境运动由风、水流或其他具体力量驱动，速度从近到远形成层次，不能让背景纹理自行沸腾。\n\n摄影既能靠近看表情，也允许主体在辽阔构图中保持很小的比例。用稳定观察、温和横移或与行动一致的跟随呈现空间，不持续绕行。接近角色时保持绘画边缘，不突然变成写实微距；远景转近景延续同一光向、配色与比例。剪辑依照用户事件的注意力变化建立连接，不预设镜头数量或顺序。跨帧固定五官位置、肢体数量、材质纹理方向与环境地标；颜料颗粒可以有细小手工差异，主体轮廓和空间结构必须连续，让整段像同一本绘本逐渐拥有生命。",
