    "promptTemplate": "让用户内容成为一则具有木雕触感的电影寓言。画面保留风化表面、手工轮廓和稀疏而有重量的构图，同时让空间拥有真实的远近、光线和空气。整体可以肃静、奇异或温柔，情绪随内容变化；不要求复制荒地复苏的情节，也不固定任何树精、旅人或精灵角色。每个形体都像经历过时间，而不是刚从精密模具中取出的摆件。\n\n角色造型使用细长支撑与较大负重体块的对照，关节与重心清晰，轮廓允许不对称。木质、陶土、旧布或石质表面以干裂、粗纹和磨损边缘区分，但主要部位必须连成可理解的结构。装饰从材料和用途生长，枝条顺着受力方向绑扎，布片有附着点，坚硬部件不在运动中随意弯曲。面部可以概括为少量凹凸与明暗，通过头部倾斜和全身姿态表达，不必依靠大眼睛。\n\n材质强调干燥、吸光与局部薄透。粗糙表面保留大小不同的凹凸，断面与完整表面有所区别；纤维状部分柔软，块状部分沉重。光沿粗糙边缘形成细小亮部，暗部仍能看到承重关系，不以纯黑吞掉全部信息。若内容包含发光或半透明的小物，保留它们的实体边缘，亮度在附近表面自然衰减，避免将整个主体变成没有结构的光团。\n\n用灰褐、烟绿、炭黑和低饱和青色组织沉静环境，按情绪加入苔绿、琥珀、淡金或暖白的局部色。冷暖变化应来自天气、遮蔽与光源，而不是每次剪辑都换一种滤镜。开阔场景里天空和地面形成不平均的重量分配，保留孤立形体与大片空处；紧密场景则让枝叶、菌落或其他环境细节围合出可进入的微型空间。两种尺度都遵循相同的材质粗糙度与光学规律。\n\n动作像有骨架和重量的手工偶，但保持叙事所需的流动性。移动先转移重心，再让支撑肢体接地；背负物、悬挂物与衣片比身体稍晚响应。角色可以迟疑、停顿、扭转或伸展，动作幅度取决于性格与材料，不让躯体持续弹性膨胀。接触时有明确落点，抓握对象之后保持连接；风只带动适合摆动的部分。若出现生长或变化，使它沿已有的结构推进，有起点、有方向、有前后状态，不能让每块表面随机融化。\n\n镜头根据内容选择远处观察、较低视角或亲密细节。移动时表现前后层次的视差，尽量让观众看清身体与环境的尺度关系；细节画面采用适度景深，焦外仍保留大形而不变成亮斑墙。剪辑以动作、视线或形状关系连接，不预设某种先暗后亮的流程。跨帧稳定角色比例、枝条数量、负重位置与粗纹走向，光辉和风尘不能遮盖结构错误；背景地形与建筑在遮挡后保持原位，整段维持有历史痕迹的手工物性。",
    "negativePrompt": "避免光滑公仔、镜面金属化、随机枝角增生、木纹像虫子游动、硬质肢体橡胶弯曲、负重漂浮、每个物件一起呼吸、整幅黑成剪影、金色光晕遮脸、森林细节均匀堆满、自动添加树精复苏剧情、无理由在写实与卡通间跳变。",
