    "promptTemplate": "将用户内容统一为具有手捏黏土触感的幻想动画。角色与布景像由真实材料搭建，世界允许梦境和夸张，但每个形体都保留稳定的厚度、连接与重量。整体既亲切又略带奇异感，情绪由用户的事件决定，不强制科技话题、占卜场景或原作角色。让材料、光线和表演共同建立风格，而不是仅在普通三维画面上叠一层颗粒。\n\n角色使用圆润而有明确转折的大块形体，鼻子、眉毛、眼睑和发束可以像分开制作后连接的部件。比例适度简化，眼睛足够表达注意力，嘴形收敛；保留每个角色自身的脸型和姿态差异。头发呈成束雕刻，不生成大量漂浮细丝，服饰用大面积色块和少量接缝表达。手部关节清楚，手指厚薄一致，动作时不互相粘连。即使是非人物主体，也以可触摸的大形和局部塑形痕迹建立识别度。\n\n黏土表面为哑光或轻微蜡质，保留非常细的压痕、接缝与不完全平整，但不将皮肤做成污脏龟裂。柔软体块的高光宽而弱，边缘有轻微圆角，阴影能说明部件之间的接触。区分木材、布、纸和金属等道具：木板有方向性纹路，织物吸光，纸片保持薄边，灯泡只有光芯较亮。所有材质共享同一环境光，不让角色与布景像不同软件渲染后拼接。\n\n配色以奶油色、深蓝、赭黄、木棕和暖红形成有生活感的基底。正常环境中使用窗边柔光或局部灯光；幻想空间可以加入暖橙灯泡、深青暗部和少量绿色发光。色光要有清楚来源和范围，照在脸上时仍保留五官结构。明亮物体与暗背景形成节奏，不把每个边缘都描上霓虹，也不让一整片饱和绿光抹平材料差别。\n\n布景像可进入的手工舞台。大小道具之间有可理解的比例，桌椅、轨道、建筑或植物围出实际行动路径，前景与背景错落但不拥挤。形状可以天真和不完全规整，支撑结构仍应成立。局部奇观由用户设定决定，使用重复结构、灯光间距和前后遮挡呈现尺度，不以随机长出的道具制造丰富。屏幕和标牌若不承担内容功能，就保留为简洁图形而非乱码。\n\n动画强调清楚的姿态、重心和有限余波。角色的眼神先变化，眉眼与嘴角随后回应，再带动头和肩；移动前有准备，落脚后有承重，停止时有短暂稳定。保留适量手工动画的停留感，但不人为让每个动作卡顿。柔软材料只在接触和表情需要时局部压缩，硬质道具维持形状。机械运动沿固定轨迹，灯光位置随道具一起移动；环境中的次要活动更轻、更慢，给主要行为留出注意力。\n\n镜头像在拍摄真实微型布景，构图简洁，视差和景深帮助说明空间。近景看得到塑形层次，远景仍保持清晰轮廓，避免突然切换成写实演员。镜头移动服务行为和情绪，不持续穿越道具。剪辑延续视线、材质和主光，顺序完全由用户内容决定。跨帧固定眼睛大小、眉毛形状、发束数量、服装色块及道具连接，保留轻微手工差异，不能用整张脸重塑或背景融化冒充定格质感。",
