    "promptTemplate": "把提供的内容呈现为有复古实体木偶气质的科幻角色动画。主体可以奇异，生活环境却保持亲近、可信和被使用过的痕迹。形体略带人工塑造感，表演有思想、有停顿，光线像在真实房间中拍摄。题材由用户决定，不复制外星小孩、电视节目或害怕入睡的情节，也不自动把所有空间改成飞船。\n\n角色用少量清楚的大形建立辨识度：头部可相对饱满，躯干收敛，手脚纤细但保持足够支撑。面部可以有较大的眼睛或其他非人特征，眼窝、鼻口与下颌仍形成连续结构，不能像贴在光滑球体上的符号。左右略有差异，表面有轻微手工塑形起伏。若用户指定机械、动物或物件主体，保留其自身特征，以大形与细连接的对照表现角色性，不一律变成同一种灰色外星人。\n\n皮肤或软壳呈现柔哑、微细而有厚度的表面。高光集中在转折处，亮度宽而柔，眼睛可以更湿润但不能变成没有内容的黑玻璃珠。近景保留眼睑和轻微表情纹理，远景减少细节。衣服与主体分开响应：织物有厚薄、接缝、滚边和自然折叠，袖口与手部相接，衣领不能融入颈部。毛毯、沙发和纸张具有各自的柔硬程度，旧木和金属也不共享同一层塑料反光。\n\n配色以灰绿、旧米白、暗红、木棕和低饱和蓝色组织。暖台灯、窗光或其他现场光源形成柔和的照明范围，较冷的反射可以照亮脸的另一侧，冷暖比例随空间关系变化。暗处保留角色轮廓、手部动作和织物层次，亮处不过曝。若内容使用屏幕光，让它影响靠近的皮肤、衣物和家具，并随画面亮度缓慢变化，不给整个房间套上闪烁滤镜。\n\n场景有真实家居的陈设逻辑。家具高度、门窗尺寸和物件摆放适合角色使用，同时保留一点旧式装饰的温度。画框、灯罩、墙纸或其他重复图案只作为有限的背景节奏，不让细碎花纹抢过主体。构图给头部和手部留出行动空间，用座椅靠背、前景物件和不同距离的灯光形成层次。奇异之处来自角色的存在与行为，不依赖悬浮装置、繁复管线或彩色烟雾。\n\n表演以清楚的注意力转移组织。角色先观察，再出现眼睑、头部和肩部的微小反应，身体动作随之发生。紧张可以是短暂屏息、手停在半空或视线迟疑，温暖可以是放松肩膀与细微靠近，不需要持续张嘴和夸张摇头。手触碰脸、衣服或其他物件时要有稳定接触，抓握后对象随手运动。躯干保持骨架感，柔软部件有有限压缩，衣物在动作之后略晚停下，不把全身做成橡胶。\n\n摄影像观察真实玩偶演员。较宽景别说明角色与家具的关系，近景让观众读懂情绪，适度景深保持室内尺度。镜头的移动和停顿跟随注意力，尽量避免持续环绕与无目的推进。剪辑衔接视线、姿态和光源，不预设固定故事或镜头顺序。跨帧固定头部比例、眼睛位置、手指数量、衣服滚边及家具布置；遮挡后角色仍然一致，表面纹理不会独立游动。整段维持柔哑材料、生活化空间与克制反应表演的统一关系。",
    "negativePrompt": "避免塑料外星面具、眼睛无限放大、黑眼珠吞掉眼睑、脸部持续融化、手指增生、衣服滚边断裂、袖口与手腕粘连、全身橡胶晃动、背景墙纸乱爬、屏幕光全屋闪烁、密集飞船管线、自动复制原片角色与睡前剧情。",
