    "promptTemplate": "将用户提供的内容表现为色彩丰沛、以身体感和材质转换推动情绪的超现实动画影像。让主体的动作成为视觉变化的原因，空间、表面与照明围绕动势作出回应。保持内容原有的角色与事件，采用略带陌生感的柔软雕塑造型、真实表演般的节奏和连续的空间关系，建立既可触摸又不完全符合现实的世界。\n\n主形体可以有饱满圆角、舒展曲线、包覆感表面和经过概括的面部，关节位置与重心路线必须可读。伸长、缩短或外形变化围绕已经存在的结构进行，变形前后保留主体的识别特征。轻薄覆盖物、厚重身体、硬质道具彼此区别；夸张集中于局部，避免所有形体同时无规则膨胀。人物不必漂亮端正，表情与动作中的犹疑、紧张和释放比精致五官更重要。\n\n为每类材质设置稳定的触感。布状表面有褶皱聚合、拉伸方向和迟滞，柔软雕塑表面以宽阔高光呈现体积，透明或液体结构有厚薄、折射与边界，粗糙区域吸收更多光。若需要转换材质，让变化从局部经过明确的过渡带传播，原来的体积与运动惯性仍在；变化完成后进入可辨认的新状态，避免始终停留在糊状中间态。\n\n色彩围绕少量强烈互补关系组织。粉红或紫色可与青蓝形成大范围气氛，暖橙、珊瑚红或内容指定的强调色用于动作峰值。颜色既出现在表面，也通过反射、透光与空气改变邻近区域。主光有方向，亮部浓烈却保留形体，暗部仍能读出连接与重量。烟气、辉光或热浪只在内容和动作需要时出现，并有密度差与消散过程。\n\n空间在可理解的建筑、地面或自然尺度上发生有限的异常。环境可以被拉伸、重排或转换触感，但在同一动作内部保留支撑面、消失点和遮挡顺序。允许前景贴近、远景稀疏，彩色空气分隔空间而不盖满主体。形体经过边界时，阴影和反光跟随变化，超现实元素与背景接受同一套照明规则。\n\n动作先从身体中心或物体的受力点发动，再传到外侧。伸展之前略微收拢，转向时重心先行，肢体或附属结构产生顺序明确的跟随；受力后的回弹保留重量，不能无限弹跳。节奏有克制的停顿、快速爆发与缓慢余韵，各层运动不同步却彼此关联。如果没有人物，用物体的压缩、旋转、展开或支撑关系表现同样的张力，不自动加入舞者。\n\n镜头应当参与节奏但不过度抢夺动作。靠近时突出肌理和形变的连接点，退远时读清完整姿态与空间作用；移动有启动、惯性和制动，变化激烈时也保留视觉重心。剪辑通过姿势、色域或运动方向建立联系，材质突变必须有情绪动机，不能以随机闪切拼凑奇观。跨帧锁定角色比例、道具位置和材质粗糙度，细小纹理与表情连续，动作完成后维持结果，不无故复位。",
