    "promptTemplate": "将提供的内容表现为一部具有哥特室内气质的角色动画。人物比例经过艺术化设计，但表演、皮肤、衣物与空间接受电影式观察。气氛可以沉静、亲密或紧张，依据用户内容决定，不自动加入死亡、鬼魂和原作人物。让情绪集中在一个眼神如何改变、一个姿态如何停住，以及人物与周围空间之间的关系。\n\n角色使用明确的长短对比塑造辨识度。鼻梁、颧骨、下颌或手指可以延长，眼窝稍深，躯干和肩部相对收敛；每个人的夸张部位应保持稳定，不在不同景别重新设计。面部保留年龄与不对称，眉眼有柔和的体块过渡，嘴唇与眼睑能完成细微表情。不要把大眼等同于稚气，也不把瘦长线条做成恶意的丑化。衣着、发型和配饰依照用户设定，数量有限、结构清楚。\n\n皮肤具有细皱纹、轻微色差和柔软的光泽，皱纹随表情在合适部位收紧，而不是像独立纹理游动。头发以稳定发束组织，少量飞发回应动作。布料、旧木、磨损皮革与金属饰物各有不同粗糙度：衣物吸光，木面带沉积感，小饰品只在正确角度闪亮。细节服务近距离观察，避免整张脸堆满毛孔、锐化和污渍。表面真实并不取消造型夸张，两者应长期共存。\n\n色彩以暗褐、烟绿、酒红、灰青和肤色组织克制的基调。日常室内使用窗光、台灯或环境反射形成自然层次；当内容需要情绪增强时，可以让红、蓝或其他较纯的颜色从门缝、邻室或明确光源进入。局部色光必须照亮相应朝向的表面，并在远处衰减，保留未被照亮的空间。高光不过曝，暗部可以深，却仍读得到人物的眼神和身体朝向。\n\n布景有被使用过的时间感。门窗、画框、家具和墙面线脚形成稳定的空间秩序，陈设与人物尺度一致，不堆积无关古董。构图允许门框截断视野、走廊延伸深度、前景人物局部遮挡；留出空处让视线或动作有去向。空间的压迫或亲近由距离、遮挡与光照建立，不必把每个墙角都弯曲成奇观。\n\n表演以细节和反应时间推进。先让注意力改变，再出现眼睑、嘴角或头部的小幅变化，身体姿态随后响应。说话时口形有自然衔接，下颌与颈部共同参与，但不夸大每个音节；聆听时允许停顿和不完全同步的情绪。手部动作有目的，触碰、抓握和放开都保持对象连续。紧张可以表现为短暂僵住或呼吸变化，不让全身持续颤动。衣服、耳饰与头发在主体动作后留下有限余波。\n\n摄影关注人与空间的心理距离。特写保留脸的完整透视与皮肤细节，较宽景别说明人物和环境的位置，镜头只在注意力变化需要时移动。焦点转换沿视线或动作发生，不反复抽动；剪辑延续表演方向、综合色和照明来源，不规定固定的对话镜头顺序。跨帧保持脸部比例、年龄特征、饰品数量、衣褶连接和布景地标，红蓝照明连续变化，不能把情绪转换误做成角色更换或皮肤融化。",
    "negativePrompt": "避免面部每帧换年龄、长鼻忽长忽短、幼态大眼、过量毛孔锐化、皱纹游动、塑料皮肤、嘴型牵动整脸、首饰复制、背景古董堆满、红蓝滤镜均匀覆盖、所有暗部死黑、无因抽搐、强制鬼魂和葬礼剧情。",
