    "promptTemplate": "将用户内容表现为油画表面、液体雕塑与可信空间共同构成的超现实艺术动画。场景保持清楚的建筑或地貌秩序，主体保留用户设定中的身份与事件，异常从材质和动作内部生长出来。整体具有古典绘画的厚度与当代音乐影像的流动性，让安静的凝视、局部变化和空间释放互相衔接。\n\n人物、器物和雕塑先拥有准确可辨的大形与连接关系，再对表面进行绘画化处理。面部可以概括，眼眶、颧骨、手部与承重点仍需支撑表演。古旧油彩呈现细密龟裂、覆盖薄层与局部堆积，笔触顺着形体和光线分布。裂纹不会每帧重新生长，颜色也不会游离在主体之外；相同物体转过角度后仍保留可对应的痕迹与轮廓。\n\n流动材质区分薄水、透明凝胶与厚颜料。薄水受到表面张力牵引，边缘细而透明；浓稠颜料在受力后缓慢拉长、堆叠和回落；半透明体积内部保留散射、折射与厚度变化。变形从明确起点扩展，沿身体、画布或物体的结构传播，产生拉丝、褶皱、聚拢和分离时都能追踪物质的去向。不要让不同物体无因融合成同一团液体。\n\n色彩以深棕、暗红、旧金、灰蓝或内容适合的古典综合色阶为基底，局部亮色作为情绪的出口。暗部厚实而不漆黑，肌理在掠射光中显露。主光来自可理解的窗、灯或环境方向，液体吸收并折返这些光色；高光随曲率移动，接触处产生可信的阴影与映色。发光、雾气和反射只用于说明空间，不持续盖住油彩的质地。\n\n空间强调前后轴线、透视和尺度对照。大面积墙体、地面或自然背景提供安静区域，画框、柱体、台面及主体之间有清楚间隔。异常可以突破原有边界，例如表面隆起、材质离开支撑面或体积扩散，但环境的结构不跟着漂移。流体经过地面时留下连续的湿润边缘，悬浮时仍与附近物体形成反射和遮挡关系。\n\n表演在变化发生之前就能读出情绪。视线、头部转动、身体倾向或物体的轻微受力先积累张力，随后局部材质开始响应；大幅变化之后留出可观察结果的停顿。黏重结构启动较慢，细薄部分略迟跟随，滴落和回收遵循重力或已经建立的超现实规则。让同一种物质始终具有相近的惯性，不能在普通转身时突然变得轻若烟雾。\n\n镜头以稳定观察、克制推进和有目的的空间揭示为主。近处看清表情与裂纹，较远位置展示变化如何影响环境；转场可通过相似轮廓、颜色或材质相接，但不把整段变成无休止的变形接龙。跨帧锁定人物比例、绘画笔触、建筑透视与光源位置，变形必须有可辨的起点、过程和完成状态。最终效果应具有雕塑的重量、绘画的触感和电影动作的因果。",
    "negativePrompt": "避免整张画面融化、裂纹随机跳动、油画变成摄影磨皮、无来源的发光液体、颜料像烟雾、玻璃与皮肤无因互换、画框和墙体漂移、液滴无体积、反射方向错误、表情每帧换脸、连续无限变形、镜头旋转掩盖缺陷、只做静图推拉。",
