    "promptTemplate": "把用户提供的内容组织成荧光色彩、漫画符号与印刷拼贴相结合的实验动画。整体具有尖锐、怪诞而幽默的情绪，画面从简洁图形中获得冲击力。不同镜头可以在平面与有限体积之间移动，但始终共享角色识别点、颜色关系和节奏逻辑；内容与故事由用户决定，不依赖固定食品、外星人或特定剧情。\n\n形体轮廓明确，允许将面部、器官、工具或建筑部件概括成圆形、楔形、矩形及不规则剪片。识别重点做得大而醒目，次要部分压缩成干净色块。保留少量不对称和手工裁切感，黑色块可以像面具一样加强结构，局部体积以简单高光说明。夸张表情由眼部朝向、嘴形和头部角度共同表达，避免只靠瞳孔乱跳或整张脸拉扯。\n\n材质形成有控制的冲突：平涂色面接触网点、刮痕、旧胶片边缘或低保真屏幕纹理，少量光滑塑料、金属和真实物件质感提供反差。纹理应按区域分配，同一表面的颗粒随主体运动，不能全屏覆盖一层固定噪声。平面拼贴边缘保持利落，叠加元素有清楚的前后次序；如果采用屏幕或窗口结构，内部画面独立运动，外框保持稳定。\n\n颜色以荧光黄绿、亮蓝、饱和红和深黑形成硬对比，留出暗面承托最亮的符号。强调色在镜头间重复，局部可交换前景与背景颜色以改变情绪，但不能每帧重新选色。平面场景使用较少的柔和渐变，具有体积的场景则保留主光方向和接触阴影，使角色走入不同媒介时仍拥有重量。白色只作为少量强对比标记，避免持续全屏闪烁。\n\n空间可以像可变舞台、漫画格或拼贴桌面，主体之间仍有明确的行动路径。用黑色留白、边框、遮挡和尺度差分开信息层级，主动作周围保留干净区域。需要深度时建立可读地面和透视；需要图形化时可以压扁空间，但压扁与恢复必须作为明确变化发生，不能在普通动作中突然失去体积。\n\n动画节奏围绕清楚的关键姿势展开。起步前有重心准备，快速行为出现方向性的拉伸，落点短暂收紧，随后回弹或进入下个动作。夸张动作仍保持关节关系与接触因果，细线、碎片或图形轨迹沿运动方向延迟散开。平静段落用视线、呼吸般的幅度变化或小范围错位建立紧张，不让所有元素持续抖动。变化可突然发生，但前后要有相同轮廓、位置或颜色作为识别桥梁。\n\n镜头在完整动作和局部符号之间切换，推近、横移或甩动由行为带动，停下后恢复可读构图。剪辑按视觉压力与释放组织，密集信息段落之后留出简单形体和明确停顿。跨帧保持角色关键色块、边框和材质身份，重复符号数量受控；任何变形都能读出起点、过程和结果，避免把随机熔化、画面跳动或平移静图当作实验动画。",
    "negativePrompt": "避免全屏均匀噪点、无层次荧光铺满、文字乱码堆叠、角色每帧换脸、圆眼珠随意脱落、肢体关节乱折、脚部在地面滑行、碎片与主体运动无关、所有纹理固定在镜头上、无故闪白、平面与体积无动机跳变、只做静图缩放、特效遮掉关键动作。",
