    "promptTemplate": "将用户内容塑造成由拟人动物参与的成熟电影动画。动物的身体与皮毛保持可信触感，人类式行为通过姿态、服饰和社会空间呈现，气质克制、安静而有张力。用户的事件决定是否悬疑，不自动加入案件、警察、井或原片角色。把不可思议的角色认真地置于一个完整世界中，让情绪由目光、距离和环境关系产生。\n\n造型首先尊重物种。保留耳朵的附着位置、吻部形状、眼睛间距、牙齿和爪部的基本逻辑，再根据动作需要调整直立姿态和手部功能。动物头部与躯干通过连续颈部连接，不能像换头面具。毛发分区顺着骨骼与肌肉走向生长，长毛、短毛、胡须与裸露鼻部清楚区分。脸部允许少量艺术化强调，但不把所有动物都换成同一种大眼人脸。\n\n皮毛具有哑光主体与细小边缘反光，毛束有密度和层次，阴影不会把它们合成一块油亮表面。眼睛湿润但不夸大玻璃反射，鼻部只在合适角度有局部光泽。衣物以厚织物、旧皮革或用户指定材质呈现，肩部、袖口和领口与身体接触，褶皱跟随姿态。磨损反映实际使用，不均匀铺满脏点；金属小件与纸张各自保持硬度和厚薄。\n\n画面使用低饱和冷蓝、灰绿、炭黑与脏白，肤毛本色在冷环境中仍可分辨。户外光线可以柔而散，远处空气降低对比，近处轮廓保有质感；室内通过窗光和局部暖灯组织明暗，暖色只照到应该受光的部位。若有红色或其他信号光，它应按真实照明范围投射到皮毛、衣物和墙面上，不成为整幅反复跳动的滤镜。黑位有深度，同时留住眼神和动作落点。\n\n场景保留生活尺度。家具、门窗、车辆和物品可以被动物使用，但不自动卡通化成动物形状。空间有活动路径、遮挡和明确地标，物件的数量与位置保持稳定。用前景人物、门框、桌面或窗外景物建立观察距离；广景说明角色关系，细节强调物证、触感或目光，具体功能由用户内容决定。天气和空气可以增强情绪，但不让雪雾遮盖整个动作。\n\n表演从注意力出发。眼睛先看，耳朵或头部适度回应，身体再转移重心；每种动物保留不同幅度和速度，不让所有耳朵机械同步摆动。交流时口部动作符合吻部结构，嘴角与鼻部变化收敛，避免把人类唇形直接贴上。站立要有承重，走动有足部接触与衣料滞后，停顿时允许眼神、呼吸或细微平衡变化。尾巴、胡须和毛发只回应相关力量，不以全身抖动填满空隙。\n\n摄影采用明确的观察轴线和自然透视，移动克制，景深保留空间线索。近景看表演，宽景看人物之间的位置，不强制围绕角色旋转。剪辑依照用户事件的因果和视线连接，保持出入方向、光线、服装及环境状态。跨帧固定物种特征、毛色分区、耳朵形状、衣扣与道具，遮挡后主体仍一致；皮毛细节可以随动作改变，却不能自行游动或忽然替换物种。",
