    "promptTemplate": "把用户提供的内容表现为具有生活纪录温度的超现实电影影像。保留人物、物件、地点与事件的原有设定，让真实可触摸的日常世界承载想象。若内容含有不可能的形态或关系，把它当作这个世界里自然存在的一件事：环境不用配合它变成奇幻舞台，角色也不必持续夸张惊讶。若用户没有指定异常设定，不额外制造怪异人物，以观看方式、材质触感和不刻意的表演建立风格。\n\n造型遵循现实尺寸与人体结构，允许普通人的不对称、松弛姿态和穿着褶皱。衣物有厚度、缝线与受力方向，生活用品有细小磨损，背景保持功能合理的陈设。用户指定的特殊物体可以改变外观，但在画面里仍有稳定体积、边界和重心；轻薄材料、硬质表面与软织物分别回应压力，不把整个人物一起变成柔软橡胶。细节分布有重点，保留生活空间的偶然性。\n\n色彩以温和的肤色、旧米白、灰蓝和自然绿构成基底，依据场景选择适量明亮的局部色，避免整幅浓烈调色。照明来自可以理解的天空、窗户或现场灯光，允许侧逆光与不完全均匀的曝光。亮部柔和收拢，暗部保持可读的层次，细颗粒不过度覆盖皮肤与眼睛。异常元素与环境拥有一致的光源方向、综合色、接触阴影及反射关系，不能像后贴的鲜亮图标。\n\n空间应有可信的公共或私人生活尺度，远近人物、门窗和物品的大小服从透视。用适度景深、经过的前景和不规整遮挡建立在场感，背景不是围绕主体自动变化的布景。若主体进入阴影、经过玻璃或被遮住一部分，色温、反光与轮廓变化应逐渐发生；被遮挡期间继续保持同一身份与结构，重新出现时不替换衣着或物件。\n\n运动按照内容的正常速度展开。身体先建立支撑与重心转移，再由相应关节完成动作，快速行为也要保留真实的加速和制动。停顿可以包含微小平衡调整、视线游移或手指松紧，但不要求每件物品都呼吸。若存在轻质、悬浮或弹性结构，让它依照自身质量与气流产生小幅滞后，和较重部分保持可解释的连接；衣摆与发束响应同一环境力，不以同步摇摆冒充自然。让人物对周围变化有适当反应时间，不把每次动作做成广告式完美展示。\n\n摄影像一位在现场观察的人，根据内容选择距离、景别和运动。跟随可以略晚于动作启动，稳定时也不必完全消除身体感，但避免无目的的持续晃动和悬浮绕行。焦点跟随可见注意力转换，保留空间线索，不用不断拉焦制造高级感。若用户内容包含剪辑，以观察重点和行为关系连接画面，延续异常设定、服饰、色彩与光线条件；普通动作和想象元素使用同一种摄影语法。跨帧保持皮肤、衣物纹理和物件数量稳定，让真实感来自连贯的细节，而不是锐化与光效。",
