    "promptTemplate": "依据用户内容生成具有有机微观触感的电影影像。人物、物品和事件依照用户设定，视觉重点放在包覆、连接、生长以及材料内部与外部的关系。把细小结构呈现为可以感知深度与重量的空间，使观众感觉靠近了平时难以看清的表面。保留主体的功能和主要轮廓，不为建立风格任意添加器官、胚胎或生物，也不把现实人物整体改造成抽象纹理。\n\n造型由有方向的纤维、连续的膜、分层壳体和不完全规则的孔隙组成，依照题材选择适合的结构。近距离细节有明确的连接点与厚薄过渡，外轮廓可以柔软，却不能像融化的胶团失去组织。若是生物材料，让分枝与层叠体现生长逻辑；若是普通物件，以纹理、磨损、薄厚和局部触感建立有机性，坚硬部件仍维持机械结构。大形先清楚，细节沿形体展开，避免无限重复的蜂窝和随机堆叠的小球。\n\n让光线与材料厚度发生关系。薄的边缘透出柔和光晕，较厚的部分保留颜色吸收与阴影，纤维和微孔有细小自遮挡。潮湿处的高光只出现在相应角度与曲率，干燥处则呈现细腻哑光。根据内容在温暖赭红、琥珀、乳白与深绿、灰青之间组织综合色，局部色差体现物质层次，不给所有材料套同一荧光色。保留暗部深度和明亮开口周围的柔和反射，不用大面积泛白掩盖结构。\n\n空间尺度由颗粒大小、表面曲率、前后遮挡和景深共同说明。靠近观察时，焦内区域包含可辨认的材质转折，焦外仍能理解大体结构；不同深度的薄膜或枝条不能同时粘在一个平面上。若用户场景允许看见内部，让开口、半透明介质或局部裂隙自然建立内外联系，不强制镜头穿过实体。镜头靠近只改变观看尺度，不能让结构凭空长出或整个空间跟着呼吸。\n\n运动体现压力、张力、黏性和阻力。柔软表面受到作用时，形变从受力处向连接部位逐渐传播，边缘连续移动；回弹幅度取决于材料，不把每次接触都变成明显弹跳。若有开合、伸展或流动，体积与连接关系保持可追踪，流体绕过障碍并在接触处形成相应弯月面。壳体、晶粒等硬结构保持稳定，只在允许的关节或接缝处运动。停顿时根据材料保留微弱的内部活动或完全静止，细小悬浮物的速度与介质一致，不能所有层次同步漂移。\n\n摄影保持亲密、谨慎的观察感，由用户事件决定是否移动及如何变化景别。运动时明确镜头自身的位移与材料形变的区别，让近处遮挡变化快于远处；焦点转换沿可见空间推进，不以反复虚实跳动制造神秘感。若内容包含剪辑，延续同一结构密度、光线性质和运动规律，宏观与细节之间保持可以推断的尺度联系。跨帧维持孔隙位置、膜的连接、对象数量及颜色边界，允许纹理随形体受力变化，不允许纹理自行沸腾或一帧一帧重新生成。",
