    "promptTemplate": "将用户内容转化为冷峻、粗粝、带有旧科幻档案气息的电影影像。人物、地点与事件沿用用户设定，不自动加入雪地、探险队、灾难或怪物。整体具有现实空间的尺寸和重量，同时保留被人工选择过的简洁构图与略显陌生的质感。让张力来自环境尺度、可见细节与未被解释的空间关系，避免以密集特效、快速剪辑或装饰性的科幻符号替代氛围。\n\n主体造型以清楚的大体块和可信结构为先。若有角色，身体姿态保留衣物负重、关节限制和工作状态，脸部有轻微不对称与肌肤纹理，表情通过视线和局部肌肉变化表现。服装、建筑与工具允许磨损、修补和不均匀色泽，但每种痕迹要贴合材质与使用方式。画面可以带有细微的绘景概括感，不能把关键结构变成模糊涂抹，也不追求塑料般光洁的现代广告精度。\n\n色彩围绕灰蓝、灰绿、炭黑、脏白和褪色土色建立有层次的低饱和关系，少量暖光或强调色按用户场景出现。照明具有明确环境依据：天空漫射、远处光源或局部灯具分别产生相应阴影与反射。亮部不过度洁白，暗部保留材质差别；皮肤和旧织物以哑光为主，金属反光窄而不均匀。少量颗粒与综合色偏移形成旧影像的触感，不添加遮住主体的划痕、胶片边缘或持续闪烁。\n\n环境具有比主体更大的稳定结构，以透视、重复设施、地表纹理和远近明暗说明距离。前景可以遮住部分信息，远处形体适度简化，但空间不能在运动中重新排列。若存在雾、尘、雨雪或蒸汽，让它们占据不同深度，并依照同一流向、光线和遮挡关系变化；用户未提供这些介质时，不用强行增加天气。接触面的阴影与痕迹说明站立、放置和移动，不让人物漂在环境上。\n\n运动保持可观察的质量和阻力。人物或机械的主动动作依照内容发生，重物改变方向需要受力，厚衣物晚于身体转向，细小附属物有有限回摆。静止区域可以真正保持安静，动作中的眼神、手部、衣领或呼吸只在相关条件下变化，不为避免静帧而让整个画面波动。若出现风或恶劣环境，阻力分别作用于不同重量的部分，主体可以用姿态补偿；剧烈动作仍保留起因与受力结果，不统一处理成慢动作。\n\n摄影根据事件选择远近关系，以观察和辨认空间为主。移动时保持稳固的水平与合理惯性，近处与远处产生不同程度的视差；没有观察动机时允许机位稳定，避免恒速数码放大与无目标绕行。焦点转换不过分频繁，景深保留环境信息，让重要细节进入观看重点时能够被辨认。若使用剪辑，各景别延续同一光源、色板、人物状态和空间方位，停顿长度随内容需要。跨帧维持面孔、设备结构、衣物纹理及背景坐标，允许局部材料自然运动，不让静止图层滑动、边缘破裂或场景逐帧改造。",
    "negativePrompt": "避免强制雪地探险剧情、霓虹赛博装饰堆砌、高饱和游戏过场质感、光滑塑料皮肤、整片均匀冷蓝滤镜、全部暗部压黑、过量划痕闪烁、强行给每个物体加运动、纸片式平移、恒速数码推近、环境随角色融化、衣物纹理游移、重物无惯性、背景坐标漂移及所有行为统一慢动作。",
