    "bestFor": "原创怪物短片、奇幻生态设定、角色喜剧、寓言式品牌故事",
    "promptTemplate": "以奇幻生物拟纪录片的方式重构当前创作内容，让观众先相信自己正在观察一个具有完整生态的世界，再逐渐发现其中生命的个性与幽默。角色使用原创的混合物种设计，先确定骨架、支撑方式、感知器官和取食或活动习性，再组织外形。夸张集中在可辨认的轮廓与少数表情部位，不把所有生物都做成同一种圆球。即使形态不可思议，也要使它看起来能够在自己的环境中生存，避免直接拼接参考角色的五官、角或身体。\n\n视觉介于精细数字绘景与立体角色表演之间。环境有绘画组织过的构图、体积和边缘层次，同时保留苔藓、岩面、叶片或其他实际材料的细节。角色表面根据其生态选择皮毛、鳞片、角质、湿润皮肤或混合材料，让材料差异有生物学位置依据；毛发只在需要的部位出现，不以全身蓬松来代替设计。眼球、口腔与身体共享同一光照和色彩环境，避免面部像后来贴上的平面图标。\n\n用自然光逻辑营造略带神秘的观察距离。环境大色块较克制，局部鲜明的生物颜色负责引导注意力；空气透视和逆光可以分出前后层次，但不能把每一处都变成发光装饰。近处材料较清楚，远处轮廓逐步柔化，暗处仍保留可辨认的形体。保持统一的主光方向和环境反射，让角色坐下、贴近地面或靠在物体上时，接触阴影把它真正放进场景。\n\n空间按生态关系而非展示台组织。前景的叶、枝、石或其他遮挡物应暗示观察者的位置，中景给角色留下完整动作区，远景建立栖息地的尺度。不同生物与同一环境的大小关系稳定，所站的平台、所抓握的结构能够承重。镜头切换时保留环境地标和遮挡顺序，不让角色变成在相似背景间漂浮的立绘；局部微风、水面或尘粒可以存在，但活动量低于主要表演。\n\n动作从动物习性过渡到有个性的反应。先用眼神、头部方向和身体重心表现注意力，再让嘴部、四肢或附属结构参与表达。表情变化需要准备、停顿和回落，幽默来自观察与回应的时间差，不依赖一直咧嘴或全身乱摆。呼吸、触须、耳部或毛发只提供细小次级动作；抓握点、落脚点和身体悬挂关系在表演中保持一致。角色之间若有交流，用明确视线目标和接续反应建立联系，不强制加入对白或音轨。\n\n摄影有耐心地寻找生命行为，在环境建立、远距离观察和表情细节之间按内容选择镜头。机位变化应揭示生物与空间的关系，靠近时保留环境线索，必要的景深变化服务于观察目标；不让每个镜头都围绕角色旋转。不同镜头延续同一套生物比例、表面花纹、器官数量和环境色温，情绪与动作从前一状态合理发展。可以保留绘景的艺术化边缘，但脸部变形、毛发增生和随机换景不能被当作奇幻。整段保持自然观察与动画表演的结合，不转成商品玩偶展示、平面贴纸或纯粹写实的野生动物纪录片。",
