    "promptTemplate": "把当前创作内容处理为一段可以进入的记忆：空间有真实生活的材料、人物与光线，却按照情绪关联而非地理规则连接。人物和物件首先具有可信的体积、重量与生活痕迹，画面不靠巨大奇观宣告梦境。选择几种与当前主题有关的视觉线索作为反复出现的记忆锚点，例如一种颜色、一类轮廓、一个光源或一种空间关系；锚点可以在不同环境中换一种形式出现，但始终让观众意识到它们属于同一段经验。\n\n色彩带有旧照片与模拟影像的距离感，使用适度偏色、柔和高光、稍低的局部对比和细微颗粒，保留肤色、织物和旧表面的差异。根据内容建立一组反复呼应的冷暖关系，让情绪变化表现为色温与明暗重心的转移，而不是每次转场都更换滤镜。明亮区域可以轻微溢光，边缘可以有运动造成的柔化，但不要把整张图磨成朦胧光斑；人物表情和重要物件仍要清楚。\n\n场景内部保留可理解的透视与前后层次，场景之间则允许梦境式的空间邻接。为转换寻找有形的连接界面：遮挡物、开口、反射、相近构图或正在延续的动作都可以成为入口。转换开始前让观众读懂当前空间，转换后给新的空间建立明确锚点。变化应在局部接触区域或视线经过的位置逐渐展开，不要让全画面同时液化；中间状态可以陌生，却必须保留观看方向、尺度线索或主体轮廓中的至少一项。\n\n动态的情绪比机械匀速更重要。人物动作保持生活中的重量与小幅犹豫，周围世界可以比人物更快地向另一段记忆滑移。加速、停留、靠近与离开按照当前内容交替，使关键表情有被看见的时间；不要把所有段落都做成没有呼吸的高速穿梭。发丝、衣物和环境细节跟随真实运动，空间变换不应顺便扭坏关节、脸部或手中物品。观众需要感到记忆在流动，而不是看见错误被不断掩盖。\n\n镜头与剪辑共同建立似乎连续的心理旅程，可选择平静观察、贴近人物、经过遮挡、改变观看尺度或借构图关系切换段落，具体方式由叙事需要决定。转场前后的视觉重心、运动趋势和光线关系至少保持一条连续线索，允许通过剪辑完成连接，不要求一次生成完成所有场景。广角空间可以带来包围感，但避免人物在边缘被持续拉伸；细节镜头也应与周围记忆有可辨认的联系，而不是孤立的装饰。\n\n跨帧稳定人物身份、服饰结构、关键物件与身体连接，跨场景保持有意选择的记忆线索。需要时间变化时，应由环境、状态或少量一致的外貌变化帮助理解，不能无缘无故换脸。容许建筑关系和非关键背景具有梦的弹性，但转化要有起点、过渡与新的稳定状态；不要同时改变所有已知信息。整部作品延续亲密、略带不真实的摄影感，不突然变成卡通或炫技特效合集。使用原创人物与事件，把参考作品的流动记忆语法迁移到当前主题，不复制其中的恋爱故事、人物造型或具体场景次序。",
