    "bestFor": "思想实验短片、虚构档案、观念音乐影像、复古超现实广告",
    "promptTemplate": "以虚构档案影像与超现实视觉论文的方式组织当前内容。每个画面都像来自一段有生活细节的旧记录，同时包含一个平静而明确的不可能关系：可以是尺度失常、物件位置违背常识、不同系统并置，或某个熟悉动作具有陌生后果。异常应该能够被准确指出，而不是把画面堆满奇怪东西。人物、物件和环境设计全部原创，不复制参考中的电视墙、悬浮汽车或其他具体构图，也不把生成的虚构片段伪装成真实历史证据。\n\n画面基底具有模拟摄影的物质感。依据当前题材统一选择色彩偏移、颗粒尺度、镜头柔度和对比范围，使不同场景仿佛经过同一种记录媒介。色彩可以采用褪色青绿、温和赭色、奶油白或其他经过压缩的组合，但应让少量局部颜色承担注意力，而不是使用一层统一棕色滤镜。表面有磨损、织物纹理、玻璃反射和空气厚度，重要结构保持清楚；颗粒附着于成像过程，不应像物体表面爬动的虫群。\n\n构图带有档案照片和观察性摄影的安静秩序。先让人物与环境关系、水平线和主要几何结构成立，再放入超现实变化。相机面对异常时保持克制，场景内的其他人物与普通物件仍按各自生活逻辑行动，形成正常与异常并存的张力。前景、中景、远景的材料尺度和遮挡要一致，即使某个物体不遵守重力，它仍须有稳定轮廓、光照、投影或其他能被感知的空间联系。\n\n动态不依靠全面变形制造信息量。让大部分画面维持缓慢、可信的小动作，只把视觉命题集中在有限的关系上：某个结构改变排列、某种运动与环境不合常理，或不同时代和尺度产生呼应。人物动作保留支撑与惯性，水、烟、布料等运动各自遵守明确规则；异常对象也要持续遵守本片为它设定的规则。持续漂浮就不要随机忽高忽低，局部重复就保持可辨认周期，避免物体在镜头之间无缘由增减。\n\n镜头和段落之间通过观念联想组织，而不是强行把所有场景接成同一地点。可以根据当前内容选择观察性长一点的停留、细节对照、形状匹配或尺度转换；每次切换都应让上一幅图留下一个可追踪的视觉问题。不同场景允许具有不同观看距离与运动量，但共享色彩、材料和观看态度。需要图形或抽象结构时，让它与具体影像形成清楚的关系，不添加无法读懂的伪公式、装饰字幕或没有功能的数据界面。\n\n跨帧稳定人物身份、物件数量、结构连接与材料特征，镜头运动引起的视差和遮挡必须合理。跨镜头保留足够的色彩或构图呼应，使片段看似来自同一套想象档案；允许时代与地点跳跃，但不要每一段都改成不同视觉媒介。抽象与具象、日常与异常之间的距离要有节奏，给观众看清差异的时间。整部作品追求冷静观看下的陌生感，避免恐怖跳吓、泛滥霓虹和持续融化，把超现实作为表达当前主题的结构，而不是随机生成素材的堆积。",
