    "promptTemplate": "把用户提供的内容转化为具有强烈身体感和材质层次的珠光写实绘画影像。内容、人物身份、地点和事件依照用户要求，风格通过造型、表面、光线与运动体现。让环境具有可触摸的真实结构，同时用概括的色面、干涩笔痕和局部锐利边缘组织画面；远观是完整的电影空间，近看能辨认出人为选择的绘画痕迹。真实感来自重量、光照和空间关系，细节密度服从视觉重点。\n\n若有角色，保留可信的骨骼结构与不完全对称的面部特征，身体可以略作修长、紧绷的造型处理，但不能失去关节位置和受力关系。轮廓由姿态和明暗塑造，皮肤、头发、织物各有自己的粗糙度。脸部与手部以少量准确的形体转折表达情绪，避免全身平均精雕；非人物主体也保持主要结构明确、局部肌理丰富的处理。\n\n色彩以浓郁但有空气感的冷绿、灰青与深色中间调形成基底，用温暖肤色、暗金或琥珀色建立局部张力。依照场景中的真实光源安排照明，允许不均匀的侧光、反射光和遮挡阴影。若物体本身有金属、晶体或湿润表面，让细碎高光随着表面角度变化依次出现；高光大小与材质相符，暗部仍有细微冷暖，不能把每件物品都变成发亮饰品。\n\n空间采用真实透视和清楚的前后遮挡。前景可以较粗粝，中景承载动作与材质重点，远景在色温、对比和细节上自然退让。接触面的投影、压痕、反射与溅起的介质必须对应接触位置。植物、石材、建筑或室内物件按用户场景选择，保留它们各自的形态，不为形成风格强行添加森林、水域或装饰物。\n\n运动呈现可感知的发力、重心转移与制动。若角色动作富于表现力，让姿态有伸展与收紧的张力，停顿仍保留平衡调整和呼吸；快速动作也有明确的着力点与落点。衣摆、发束、饰件等次级部分晚于主体响应，经过有限回摆逐渐平息；坚硬物件保持形状，软材质只在受力位置弯折。环境变化由碰撞、风或其他已存在的原因触发，不能所有元素同步摆动。\n\n景别、机位和镜头运动依照用户内容选择，用透视、遮挡和适量景深支持观看重点。移动摄影有惯性，追随动作时保留适当空间，主体停下后不必机械地同时停机；避免无动机的漂浮绕行。若内容包含剪辑，保持人物运动方向、空间方位、光源性质和材质反应连贯，不同景别仍使用同一种绘画密度逻辑。跨帧维持身份、骨架、服装接缝、物体数量和表面纹理的附着位置，允许笔触随形体转动，不允许笔触随机游走或五官在运动中重画。",
    "negativePrompt": "避免通体塑料亮面、均匀撒金粉、所有表面同步闪烁、暗部完全糊黑、无结构的油画滤镜、皮肤蜡化、人物骨架漂移、饰品增生、硬物软化、脚底滑行、衣物无惯性、背景随主体融化、纹理脱离表面爬动，以及缺乏动机的旋转漂移摄影。",
