    "promptTemplate": "依据用户提供的内容，生成具有手绘生态图景气质的动画影像。整体像一幅有自身生命规律的概念绘画被轻轻唤醒：形体由不透明的矿物色、干刷边缘、细铅笔线和少量半透明罩染构成，保留纸面颗粒与颜色叠压的痕迹。重点在于形状设计、生态关联和空间气氛，不以增加奇怪器官或发光粒子代替想象力，也不擅自改变用户指定的题材。\n\n把主要形体概括为可记忆的轮廓与少量内部结构。若用户内容包含虚构生物或植物，可由自然界的分枝、壳体、叶脉、膜翼和支撑结构发展原创形态，每一种形态都要有清楚的连接方式、关节逻辑与生长方向；若内容是现实人物或物品，则保留其身份与功能结构，使用同样的手绘色面表达。造型允许柔和的不规则和轻微不对称，尺寸关系在整个环境中保持一致。\n\n色板偏向赭黄、黏土红、鼠尾草绿、灰蓝与温暖纸白。大面积色块保持克制的饱和度，少量更鲜明的颜色标记用户内容里的重点。光线呈柔和的漫射或经过介质过滤的状态，明暗转折简洁，阴影保留综合色而不只是加黑。粗糙表面吸光，薄膜或湿润部位可以有局部透光，但不要让整个世界覆盖写实镜面反射。笔触属于具体物体，不能像透明滤镜一样固定在画面上。\n\n空间通过相互遮挡、尺度递减、色温变化和空气层次建立。远处形体更简约，近处出现可读的边缘纹理；各层都有独立体积，不是几张平面背景机械错动。依据用户场景组织疏密，让局部复杂结构和安静色块相互平衡。若有环境生态，运动、栖息位置与可见环境条件相互联系，既不凭空增加群体，也不让原有对象随机消失。\n\n运动强调生命的内在节律。主体按照用户指定的动作发力，柔软部分表现延迟、拉伸和回弹，坚硬支撑维持稳定长度；身体转向由质量较大的部位带动，细长附属部分沿途跟随。静止时可出现局部、低幅度的呼吸或形态松弛，停顿具有重心，不让整个轮廓持续沸腾。环境的摇摆、漂浮或流动受同一风向、介质阻力与接触关系约束，不同尺寸的对象响应速度不同；动作激烈时仍保持清楚的轮廓与生物结构。\n\n摄影根据用户内容选择观察距离和移动方式，空间移动时用正确的近远视差展现层次，避免把数字推近误作场景伸缩。景深与焦点要保留手绘形体的可读性，不依赖大量散景遮盖背景。若存在剪辑，可改变观看重点，但延续同一色板、笔触尺度、天气条件和形态设计。跨帧保持主要轮廓、结构数量及纹理位置，色层可以随受光和运动自然变化，避免每一帧重新发明生物、笔触和空间。",
    "negativePrompt": "避免通用塑料三维、荧光蘑菇堆砌、无原因增加触手或器官、全景一同呼吸、轮廓沸腾、纸纹固定覆盖镜头、画笔纹理游走、关节数量变化、硬壳像橡胶融化、平面图层穿帮、空间随着推镜膨胀，以及所有对象以同一频率摆动。",
