    "promptTemplate": "将用户提供的内容处理成冷色、锐利、富有图形张力的二维赛璐璐动画。以清楚的剪影、倾斜的形体切面和经过选择的线条建立视觉语言，使用少量大色块表现体积，避免用连续渐变填满所有结构。画面具有明确的方向和节奏，但具体人物、场景与事件保持用户设定；风格来自造型和运动设计，不要求冰原、都市或任何特定剧情。\n\n若有角色，采用稍修长而有棱角的体态：肩背、颧骨、膝肘和服装折面可以被概括为简洁的斜面，手脚与面部特征保留可辨认的形状。剪影在站立、转向与受力时始终清楚，肢体与躯干之间留出必要的视觉间隙。非角色物体沿用同样的几何概括，主要结构和用途不能因装饰性变形而丢失。线条在受力处、遮挡处和阴影边界有所强调，亮部可减线，避免每个细节都用等粗黑线围住。\n\n色彩围绕冰蓝、青灰、靛蓝和偏冷的白色组织，用小面积暖色或明度差引导注意。光照通过边界明确的阴影色面表现，转折有设计感但仍对应形体和光源；不把阴影画成随机贴纸。保留较大的安静色块，让深色剪影、亮面和空隙互相支撑。材质主要靠色面边缘、线条密度和少量纹理区分，不加入写实皮肤毛孔、复杂镜面反射或过量体积光。\n\n空间可以使用夸张但自洽的透视，以斜线、层次遮挡和体块大小形成压力或速度感。前中后景的明度分组清楚，装饰细节不能切碎主要动作。视角改变时，建筑与道具的轴向、接地位置和大小关系延续，背景可以简化却不能像纸板般任意扭转。构图疏密随用户内容变化，保留主体运动和视线所需的空间。\n\n动作以有设计的关键姿态建立节奏。发力前允许压缩或蓄势，位移阶段轮廓简明，落点具有制动与重量；静止姿态可有有意识的保持，随后转换要果断，不能把有限动画理解为整幅画面卡顿。快速运动可做受控的拉伸和形状概括，动作结束后回到既定结构；脚掌接触面和身体重心相互对应，衣角、发梢等轻部件短暂跟随。不同对象拥有符合质量与情绪的节律，不同时起步、同时停止。\n\n摄影强调空间方向与姿态可读性，按用户叙事选择机位、景别、运动和剪辑，不以固定横移代替镜头设计。镜头运动与主体位移分开处理，快速运动时保留足够稳定的视觉锚点。若跨镜头，延续视线、行进方向、形体比例与阴影分组，让画面张力来自构图变化。跨帧保持面部标记、线条粗细逻辑和色块边界附着于物体；遮挡后重新出现的部分恢复正确结构，避免新增肢体、阴影跳面或透视反复翻转。",
    "negativePrompt": "避免圆润玩具造型、平均粗黑描边、柔焦水彩化、写实毛孔和金属反射、无结构渐变、阴影随机跳面、线条抖动、伸展后比例无法复原、脚底滑行、整幅画面等频卡顿、人物与镜头同步漂移、背景透视翻转及动作剪影粘连。",
