    "promptTemplate": "根据用户提供的内容，构建纸偶插画与微型立体布景并置的黑色电影动画。角色和部分道具具有手工绘制、裁切、拼接的平面感，环境则拥有可辨认的墙面、地面、纵深与投影。让不同媒介在同一光照和空间中成立，保留手工制作的不齐整，却不让画面像廉价贴纸拼贴。用户指定的主体、地点和事件保持不变，不自动改写成侦探、外星或悬疑故事。\n\n角色由清楚的头部、躯干、四肢和服装形块组成，体态可以略带夸张和不对称，但同一角色的面部布局、关节位置与身体尺寸持续一致。轮廓允许铅笔线、干墨痕和轻微毛边，内部用有限的色块、短线和图案交代质感。纸面颗粒附着于部件，转动时跟随形体；眼睛、嘴部与细小配件像有明确位置的绘制元素，不在面部游移。用户提供的物品则保持可识别的功能结构和局部图案。\n\n环境以实体模型般的体块和有节制的磨损呈现，墙角、接缝、台面厚度和不同材质的接触关系清楚。综合色偏石油蓝、黑绿、灰褐和烟熏中间调，用有限暖光或偏黄的实际光源制造关注点。明暗分区大胆，光线可经门窗、物件或环境结构遮挡，形成有来处的切割阴影；暗部留出层次，关键表情和动作不被黑色吞没。纸偶投影与所在平面吻合，边缘没有均匀发亮的抠图光圈。\n\n空间由前景遮挡、中景表演与后景布景组成，层次有可读的间距，物件经过彼此时按真实顺序遮挡。平面角色进入立体空间时保持接地点和影子，透视变化适度，不突然变成圆润写实三维人物。纹理和小瑕疵只提供尺度与触感，不能不断增加污渍、折痕和道具。\n\n运动带有纸偶定格的离散节奏。以明确的姿态改变、有限的局部动作和有意识的保持形成表演，停顿仍有视线和重心意图。转动围绕关节或支点发生，部件有不同的响应顺序，坚硬纸片保持形状，柔软边缘可以轻微弯曲。快速动作遵从用户要求，但要保留起止姿态与接触点；不要为了定格感让整张背景一起跳动。衣角和悬挂物的回摆幅度克制，步行、推动或碰撞都有质量传递。\n\n镜头按内容选择观察关系，移动时保持布景真实视差和纸偶轮廓可读性，不以持续环绕暴露不必要的平面穿帮。若有剪辑，角色设计、环境方位、主光方向与色彩密度相互衔接，剪辑可以改变节奏而不改变材质。跨帧保持插画细节、纸片边缘和布景接缝稳定；遮挡后恢复同一部件结构，避免面部重画、关节溶解和背景细节自行生长。",
