    "promptTemplate": "把用户给出的内容转化为具有绘画粗粝感、空间张力与身体临场感的电影动画。真实的形体和动作建立可信度，大胆省略的色面、速写线和干刷笔痕建立视觉个性。主体清楚而背景有选择地概括，画面像经过设计的都市绘画，但场景、时间和情节服从用户内容，不擅自添加追逐、雨夜或城市标志。让紧张感来自空间、明暗与动作的关系，而非持续震动镜头。\n\n若有角色，保持接近真实的身体结构和鲜明的个体面貌，面部、手部和动作轮廓拥有较高完成度，次要部位可用少量色面归纳。五官有非对称与细微体积，皮肤在光下保留冷暖过渡而不过度磨皮。服装具有真实厚度、缝线方向和褶皱的受力逻辑，布料质感可以精细，轮廓与局部色块则保持手绘的选择性。若主体是产品、建筑或环境，同样将准确的主要体块与松动的次要笔触结合。\n\n光照使用局部而有明确来源的综合色：青蓝、青绿与洋红可以在不同光区形成对照，中间穿插偏暖肤色、灰白或低饱和综合色。依据实际场景调整色彩强度，日景也保留冷暖错位与绘画概括，不把所有内容染成霓虹夜景。高亮区轮廓可以破碎，暗部合并成有结构的形块；表面反光受材质粗糙度、视角与光源位置控制，少量耀光不能遮住主体。笔触形成形体，不是在写实影像上叠加均匀油画滤镜。\n\n环境采用具有方向感的透视，斜向体块、前景遮挡和深处色点形成空间层次。复杂场景中细节密度有高低，视觉重点周围清晰，次要背景可由速写和色块说明。镜头移动时，建筑轴线、开口位置、地面关系与反射对象维持一致，前景掠过产生真实遮挡，不用全景拉伸制造速度感。不同表面在同一空间中接受相互关联的照明。\n\n动作具有真实的身体重量与不完全整齐的节奏。根据用户给定动作呈现发力、犹豫、转向或停顿，快速动作有明确的重心和接触点，静止时保留微小的姿态调整。衣物、头发和随身物品受惯性影响，响应先后与材料重量有关，不能像一层粘在身体上的纹理。动作带来的模糊或轮廓概括有方向、有范围，停止后恢复清楚结构，不将拖影当成额外肢体。\n\n摄影按叙事需要选择稳定观察、贴近跟随或更有张力的移动，保留观看者能够理解的空间锚点。机位变化可以大胆，但不能无缘无故绕圈、穿透物体或突然改变焦距。若包含剪辑，通过运动方向、视线和空间位置衔接，色彩对比与笔触密度延续，不因切镜换成另一种渲染风格。跨帧保持人物身份、服装图案、受光区域和场景结构；绘画边缘随形体更新，纹理不能自行爬行，面部不能在阴影进出时重新生长。",
    "negativePrompt": "避免整屏霓虹染色、无来源彩光、均匀油画滤镜、角色塑料化、脸部磨皮、服装贴身不动、无因相机抖动、镜头穿物、建筑熔化、反射对象错误、拖影成为额外肢体、阴影进出时变脸、所有区域同等锐利及跨镜头渲染风格突变。",
