    "promptTemplate": "根据用户提供的主体、环境和事件，形成带有水族梦境气质的电影写实影像。以可信的摄影质感承托轻微超现实的视觉关系：皮肤、实体物件和空间仍有真实结构，透明介质、反射和散射光带来悬浮般的感受。保留用户内容的身份、动作和实际空间，不为了风格自动添加水母、人像、鱼缸或水下情节。若场景没有液体，把柔和的透光层次与流动节律用于已有的光线和材质。\n\n主体造型接近真实，细节遵循视觉距离。若有人物，保留自然皮肤的细小起伏、面部非对称和清楚的眼部结构；若是动物或物品，保持解剖或制造结构、边界厚度和体积。透明、半透明与不透明部分清楚区分，玻璃具有厚度和表面反射，薄膜有柔软边缘，液体有连续体积与界面，不能把所有材质做成同一种发光凝胶。\n\n色彩以低照度的深蓝、青色和有空气感的灰绿组织，用自然肤色、柔白或少量温暖反光建立平衡。光源透过介质时发生可理解的衰减和扩散，焦散只出现在具有相应光学条件的表面。高光保留形状与细节，不出现大片无结构白斑；暗处仍能辨认轮廓和前后层次。散射光、折射和反射随观看角度改变，而非作为固定图案覆盖画面。\n\n通过透明层之间的距离、遮挡、反射强弱与焦点层次构建空间。主体与透明物体发生重叠时，仍能判断哪一层在前、哪一层在后；折射允许局部形变，但主结构在离开介质后恢复正常。若存在玻璃隔层，它的边缘、厚度和接缝延续，不能在主体移动时忽然消失。景深用于引导观察，主要动作和重要结构不能长期淹没在虚焦中。\n\n运动以不同介质中的阻力和质量差异为基础。用户动作需要快速时保留速度，柔软附属部分表现适当的延迟和拖曳，停下时有有限的回摆与逐渐稳定。若有漂浮对象，位移和转动受浮力、流向及形状影响，薄膜边缘比中心响应更快，脉动或收缩牵动周围部分而不是整物等比缩放。若人物静止，只保留自然呼吸、视线变化和微小平衡调整。不同层面的环境变化互有关联，却不机械同步。\n\n摄影遵循用户内容，以观察关系选择距离、景别和机位。镜头移动带来合理视差，焦点转移有明确对象和自然过渡，不反复自动抽动；镜头漂移的速度与场景尺度匹配。若跨镜头，延续主体身份、玻璃位置、介质边界、光源性质和综合色，不强制相同构图。跨帧维持物体数量、透明结构和反射对应关系，避免脸部通过玻璃时换脸、柔软结构无因增生或光斑无规律闪烁。",
