    "promptTemplate": "将用户提供的内容呈现为被真实摄影机观察的微缩世界。主体、场景与事件保持用户设定，通过统一的尺度关系、选择性清晰区域、实体材质和精确的小幅运动，产生可触摸的模型感。环境像经过细致搭建的缩小实景，拥有可信的表面与重量，不把画面简单处理成中央清楚、上下模糊的滤镜，也不强制改成城市、交通或人群题材。\n\n形体以清楚的整体轮廓和少量关键细节为主。若有人物，姿态与服装色块承担身份辨识，五官细节随观看距离自然简化；若是动物、车辆或其他物件，保留主要结构和尺度线索。所有对象共享同一套相对大小关系，门窗、台阶、家具、植被和人物之间的尺寸可信，移动过程中不随意改变。细节精度适合微缩场景，避免一边是巨大毛孔、一边是无纹理塑料。\n\n材质具有摄影可见的粗糙度、边缘厚度和细微制作痕迹：漆面、织物、石材、玻璃或叶片分别反射光线，表面细节不能比物体本身更抢眼。光照遵循场景中可理解的主光与环境反射，阴影落在正确接触位置，明暗帮助读懂体块。色彩可略有浓缩，但保留综合色与自然明度层次，避免所有元素同时变成高饱和玩具色。\n\n空间从整体布局和相互遮挡中建立，用户内容中重要的区域拥有连贯的地面、通道或支撑关系。清晰范围具有一致的光学方向与深度，主要动作所在的空间可读，离开焦平面的区域逐渐柔化；焦平面随相机位置和观察方向自然调整，而不是锁在屏幕某条横带上。允许依据内容选择俯看、平视或近距离观察，微缩感由尺度、光学和材质共同维持。\n\n运动具有小世界的鲜明节律，同时遵守质量与接触逻辑。角色以概括而易读的姿态行动，迈步、转弯、停下都存在重心变化；轻小物体可以更灵活，较重物体有更明显的惯性和制动距离。若有多主体，活动各有起止、路径和短暂停顿，局部事件形成层次，不让所有角色复制同一种动作。快速节奏依照用户要求处理，不自动把生活场景变成延时摄影；车辆与脚步沿实际支撑面移动，不能漂浮、穿模或瞬间换位。\n\n摄影依据用户内容选择景别和运动距离，相机移动要与模型尺度匹配，近景经过物体时产生正确视差。移动或焦点变化不应让场景像橡胶一样拉伸，清晰区域切换仍让观者理解关注对象。若有剪辑，保持地点布局、相对尺寸、光线方向和活动关系，不因景别改变让人物忽大忽小。跨帧延续物体数量、接地点、路线和材质细节；远处对象简化后仍保留身份特征，遮挡后重现的物体不改变颜色、形状或运动目的。",
    "negativePrompt": "避免固定在屏幕上的模糊横条、过度虚化主要动作、全体塑料玩具色、相对尺度漂移、近景巨大毛孔、阴影悬空、人群复制、脚底滑行、车辆穿模、所有对象同步启停、无因延时加速、镜头移动导致模型拉伸及遮挡后换物。",
