    "promptTemplate": "按照用户提供的内容，构建以液态折射、透明薄膜和光的体积为核心的抽象光学影像。将形体看作可以承载光、弯曲光和遮住光的连续物质，形成深色空间中有层次的流动结构。若用户内容是具象物体，保留其主要轮廓、识别特征与行动意图，用光学材质重新组织视觉；若内容本身抽象，则围绕其色彩、形状和变化方向发展，不自动追加黑洞、星球、隧道或特定剧情。\n\n造型具有清楚的内外边界和厚薄差异：厚处像有黏度的透明体积，薄处可以形成卷曲膜边、细带与局部褶皱，接近边缘时反光和透光产生变化。形体之间的连接关系可辨认，空隙是真正的负空间，不是随时填满的噪点。必要的细颗粒或点状高光有位置与运动轨迹，密度克制。几何对象若未被用户要求变形，保持主要结构，不因为液态风格而完全融化。\n\n色彩以深黑、靛蓝、紫色、冷白及有限暖色交织，透明色层叠加时产生有逻辑的综合色。发亮的部分来自光源、透射或界面反射，不让所有边缘同等发光。厚度增加时透光逐渐衰减，弯曲表面使后方形状发生局部放大、压缩或偏移；不同表面的光斑随角度和曲率连续移动。高亮有细节，暗部有层次，允许局部柔化和色散，但不把整体处理成过曝霓虹云。\n\n空间由近处膜边、中间流体体积、较远的光与负空间建立，前后层通过遮挡与折射关系清楚区分。若用户内容需要开阔空间，保持足够的空隙；若强调密集结构，仍区分主体与细节。摄影距离改变时，厚度、曲率与各层位置保持一致，不能只是平面纹理被放大。透明物体遮住另一对象时，后者仍有稳定位置，离开遮挡后恢复正确形态。\n\n形变围绕黏度、表面张力与局部受力展开。流动经过细窄处会拉伸，转向时有延迟，膜边和细丝在张力作用下收拢或回弹；较厚部分运动更稳，较薄部分响应更敏感。若用户要求分离、合并或转化，让接触、连接变化和体积重新分配有连续过程，避免所有区域同时随机变形。停顿时主要体积趋于稳定，仅残留局部松弛；点状元素沿已有流向移动，不能逐帧无因出生和消失。变化幅度与速度由用户内容决定，不强制循环或固定终态。\n\n镜头根据需要观察整体流场、体积关系或表面细节，移动有明确观看目标与合理惯性，光学变化主要由相机和物面关系产生。若存在剪辑，延续材质规律、色彩关系及运动能量，允许形态变化而不突然换成烟雾或固体碎片。跨帧保持主体结构、流向、光源和折射对象的连续性，复杂区域也应有可追踪的形变路径，避免以随机闪烁、万花筒对称或全景扭曲代替真实的液态运动。",
