    "promptTemplate": "将用户提供的题材与内容统一转译为具有纪念碑感的图形动画美学。整段视频的识别点是经过提炼的大形、果断的色块、极少但明确的视觉重心，以及渺小对象与巨大空间之间的尺度关系。保持原内容中的人物、物品和事件自由，只改变它们被造型、照明和组织运动的方式；不同画面应像来自同一部严谨设计的动画电影，而不是一组独立插画。\n\n造型以长直线、斜切面、修长弧线和简洁几何结构建立轮廓。人物可适度拉长，但关节、重心与表情仍能辨认；建筑、道具或自然形态保留最关键的识别特征，再把次要细节归并为大的明暗面。远处形体以剪影和层级表达，近处才出现少量结构线，避免平均铺满纹理。轮廓有明确转折而不僵硬，内部细节始终服从外部大形。\n\n色彩采用有限而有纪律的主色组：深蓝黑与冷灰负责体积和负空间，高纯度青蓝作为贯穿全片的视觉锚点，必要时用少量锈红、橙黄或暖白形成对照。亮色面积可以随内容变化，但色相身份与主次关系连续。光照像精心安排的舞台侧光或边缘光，用宽阔、整洁的阴影切分形体；发光区域边缘明确，暗部保留层次，材质偏哑光绘画与轻微印刷颗粒，不让每个表面都反射高光。\n\n空间强调可读的前后遮挡、稀疏的景深层级和大胆的留白。通过重复形体、远近尺寸及极少量细节建立尺度，不依赖密集雾气。重要对象周围有足够的空域，让视线能够停留；环境既有真实的透视支撑，也保有平面海报的整齐秩序。可按照原内容选择对称、偏心或斜向构图，但画面中的主要力线要相互呼应。\n\n运动以清晰姿态和有意停顿组织时间。按动作需要选择可辨认的蓄势、方向明确的位移、制动或停顿，节奏服从用户内容；不要持续匀速摆动所有对象。大体量物体具有沉稳惯性，细小对象可以更灵活，背景运动保持低频、低幅度。加减速顺畅但不油滑，关键姿态保持轮廓可读；如果内容有快速动作，也应保留起点、受力方向与落点的图形关系。\n\n摄影与剪辑服务于尺度和认知变化。可在需要时从局部质感转向空间关系，或用安定的观察让一个形状逐渐显露意义；镜头运动尽量少而准确，不预设统一路线。切换画面时延续主色、轮廓方向或视觉重心，节奏有疏密与呼吸，不靠连续甩镜和眩光维持注意。所有镜头共享一致的轮廓粗细、阴影硬度、青蓝色锚点和颗粒尺度；人物比例、服饰边界、建筑结构与光源位置在运动中稳定，几何面只随合理透视改变，不自行融化、增生或跳变。",
    "negativePrompt": "避免满屏微细纹理、颜色平均高饱和、阴影边界跳变、过量镜面高光、无目的连续旋转、图形面融化、人物比例漂移、运动中建筑线条弯曲、每帧颗粒重新洗牌。",
