    "promptTemplate": "把用户提供的内容表现为清线漫画与立体动画融合的迷幻视觉体系。画面同时具备精确的线条、可触摸的空间和逐渐变化的感知，让日常或幻想题材都像进入一部色彩鲜明的图像小说。保留原本的对象、环境与叙事意图，不指定角色身份或故事结局；风格应贯穿从安静细节到广阔空间的全部画面。\n\n外轮廓以细而稳定的深色线描清楚勾勒，结构线有选择地说明折面、接缝和表情。线条跟随真实体积转折，粗细略有呼吸，但不变成厚重漫画黑框。物体造型可略作修长或柔化处理，仍保留可信的受力关系。材质采取平涂、少量细密排线与克制的绘画颗粒，阴影主要归纳为两到三层色阶；玻璃、织物、岩石或金属依靠各自不同的边缘与高光形状区分，不用照片纹理覆盖整幅画面。\n\n色彩以明亮的矿物黄、赭橙、杏色构成温暖段落，以青蓝、钴蓝、紫罗兰构成冷色段落。颜色变化反映气氛与观察方式的转变，而不是随机换滤镜；即便只使用一个色域，也保留一个低面积的互补色线索。光源形成可读的大块投影与细窄轮廓光，局部透光和反射带来湿润或晶体般的感受。高饱和度区域不同时抢夺焦点，肤色或关键对象的固有色在冷暖光下仍可追踪。\n\n空间让熟悉形态与陌生的尺度关系并存。将近景、中景、远景做成连续的层次，地面、墙体或其他环境表面保持清楚的透视与接触关系。远处的结构可以更加抽象，局部轮廓可出现重复、回声或地貌般的节律，但不要强迫每个场景变成外星荒野。空气、薄雾或细小悬浮物的密度有前后差异，造成轻微水下般的通透与漂浮感，同时让主要动作保持易读。\n\n时间运动有两种相互支撑的质感：具体对象的动作保有重量、呼吸、支撑与自然迟滞；环境中的柔性层次以缓慢、连贯的波动或流动表现感知。若原内容需要超现实变化，让形状沿已有线条与结构逐步转化，变化具有起因、方向和持续性，不随机抽搐。细小运动不会完全同步，前后层有轻微相位差；重要表情和手部动作宁可克制，也要前后连贯。\n\n摄影带有观察与沉浸的气质，依据内容选择稳定取景、柔和跟随或轻微漂移，让观众能够阅读线条和空间。剪辑可让色彩、弧线或动作方向在不同画面之间接续，转场不必都使用变形；需要停顿时允许真正安静，需要增强情绪时让景别、运动和色彩共同变化，不突然把全片改成高速预告片。保持同一套线条密度、阴影分层与材质颗粒，人物特征、物体拓扑和空间朝向跨帧一致；发光与倒影遵循同一个光照逻辑，轮廓线不在闪烁中重新生成，动态模糊只辅助速度，不能抹掉漫画造型。",
