    "promptTemplate": "将用户提供的内容塑造成数字墨线与发光幻境结合的动画影像。整体保留可信的立体空间、自然表演和手绘漫画的观察感，再让半透明色层、局部自发光与移动的彩色照明带来奇异而温柔的气氛。用户的题材、对象和事件保持开放，视觉魅力来自普通实体与轻盈光体之间的材质反差，不依赖某一种动物、夜景地点或既定故事。\n\n实体对象用有笔锋变化的深色轮廓线与少量内部速写线塑形，面部、衣褶、结构转折等重点处保留细微的不规则。线条依附于体积并随遮挡合理消失，不能像浮在表面的描边滤镜。颜色归纳为简洁而协调的面，暗部偏哑光，皮肤、木质、布料或旧金属仍有各自的触感；局部保留细小擦痕和绘画颗粒，但细节密度让位于角色表情与动作。\n\n色彩从原内容的环境出发建立一组稳定底色，再选少数琥珀金、珊瑚橙、青绿、蓝紫作为发光或反射色。深处可以沉入冷蓝、暗紫或棕黑，亮处仍有干净的色相，不把暗景整体抬成灰雾。发光对象不是均匀亮白的灯泡：外缘、内部结构和半透明躯体具有不同亮度，内层纹理可像纤维、脉络或细线，让观众看见层叠关系。光晕范围有限，最亮的部分仍保留形状。\n\n让光真正参与空间。发光层靠近实体时，相邻表面出现对应颜色的柔和亮面；它经过时，亮面沿着物体曲率与遮挡关系滑动，再逐渐衰减。背景保持深度，前景光点更大更清楚，远处光群稀疏且更弱，不能把整幅画面铺成同一平面的粒子屏保。透明层的前后遮挡、穿透与反射遵守同一套设定，实体保持稳定重量，轻盈对象才承担漂浮感。\n\n运动采用自然表演与流体般次级运动的对照。若出现人物，视线、呼吸与重心调整可以引出动作，手势带有细小迟滞；其他实体按自身结构与受力关系运动，接触地面时有明确支撑。轻盈对象沿连续弧线运动，前端引导、后部逐节跟随，减速和转向时有柔软的延迟；群体遵守共同流向，同时保留个体间的距离、速度与相位差。不要让全部对象同频摆动，也不要用随机闪烁代替生命感。没有发光生物的题材，可以将这些规律应用于织物、光带、烟雾或其他适合的元素。\n\n摄影保持亲近而有耐心的观看方式，景别和镜头运动由内容决定，让表情、材质接触与光的经过有被感知的时间。剪辑可以借动作、视线或颜色呼应衔接画面，情绪增强时适度提高运动密度，仍留下安静的间隙；不强制固定取景或固定路径。整段保持墨线粗细的分布、实体与光体的比例关系及稳定色板。跨帧锁定面部特征、附属物数量、纹样位置和遮挡顺序，光体内部纹理随形体运动而移动，反射跟随光源，避免纹理游走、轮廓重画或亮度突跳。",
    "negativePrompt": "避免全场铺满同速粒子、实体和光体同时透明、墨线漂浮、发光区域一片纯白、无来源的光斑跳动、反射方向错误、群体相互融合、纹样游走、人物变脸、全画面同步摆动。",
