    "bestFor": "玩具品牌故事、轻喜剧角色、童趣科普、手工质感片头",
    "promptTemplate": "以可触摸的手工黏土模型作为整部作品的共同视觉语言。按照当前创作内容设计原创角色、物件与环境，把复杂形态归纳为捏塑的球体、短柱、厚片和弯曲块面；轮廓略有不对称，但关节位置、支撑结构与重心清楚。面部通过少量立体五官和有厚度的嘴形表达情绪，不套用真人皮肤。小物件也要有独立制作后装配的感觉，尺寸经过有意识的简化，让重要动作在远景中仍然可读。\n\n材质必须像带细微压痕的哑光黏土，而不是光滑塑料。表面保留轻微指压起伏、拼接缝和工具划痕，这些细节跟随模型表面运动，不能每帧随机换位置。需要表现毛发、树皮或衣料时，用雕刻沟槽、叠压薄片与有限纹路代替照片纹理；不同材质通过刻痕尺度、边缘厚薄和反光宽度区分。质感应有重量与柔韧性，避免为了强调手工感而让整个模型不停融化。\n\n为当前内容建立克制而明确的色板，主体与环境在明度或色相上分开，颜色像预先调好的有色泥料。使用柔和的大面积光源，让圆润体积、凹槽阴影和接触面自然显现；高光宽而弱，阴影边缘柔和但方向稳定。暗部仍保留材料颜色，不把每条缝都描成黑线；场景里的发光物可以产生局部色染，但不要破坏整体棚拍模型的观感。\n\n空间像认真搭建的小型摄影布景，前景道具、中景表演区和远景轮廓各有用途。根据内容选择立体模型、薄片景物或绘制背景的组合，让地面接触、遮挡关系和可行走路径成立。景深帮助观众理解层次，不要把所有远近物体都虚化成奶油背景；必要的环境纹理应随着距离变简洁。角色经过道具时，遮挡边缘、投影和相对尺度保持可信。\n\n动作带有逐格摆拍的节拍：蓄势、发力与制动清楚可读，停顿和节奏依照用户内容选择。运动可以略有分节，关键姿势之间仍须保持因果和空间连续；不要用随机抽帧、抖动或全画面跳位冒充定格。脚掌落地要有支撑，手部接触物体后才带动物体，柔软部件允许小幅压缩与回弹。情绪变化主要由头部角度、肩部和嘴形共同完成，次要动作稍微滞后，避免所有部件同步摆动。\n\n镜头应像面对真实微缩布景工作，按叙事需要选择观察距离、机位变化和剪辑节奏，始终照顾模型的体积与动作可读性。大景交代角色和道具的位置，近景让刻痕、表情与接触动作有意义；镜头移动时保持稳定透视和前后景视差，不穿过实体布景。镜头之间保留同一套角色比例、泥料颜色、表面刻痕与光照逻辑；动作衔接时延续姿态、道具状态和运动方向。全片保持手工模型语法，不突然转成真人摄影、光滑商业三维或二维贴纸，也不复刻参考影片中的角色、道具组合与剧情。",
    "negativePrompt": "避免光滑塑料、写实毛孔、照片贴图、液态融化、随机抽帧、整幅画面抖动、脚底滑行、关节漂移、刻痕跳变、道具穿插、跨镜头泥料换色；不要复刻参考角色与剧情。",
