    "promptTemplate": "把当前内容转化为具有柔软填充物和真实绒毛触感的原创玩偶动画。角色造型以清晰的大体块和柔和曲面组成，先确定头部、躯干和四肢之间的比例，再添加有识别度但不过量的局部特征。眼睛、嘴部和手脚需要在绒毛中有明确位置，表情可读而不追求真人解剖。形体可以有夸张，但必须让观众理解它如何站立、转身、拿取东西和维持平衡；不要依赖参考中的具体怪物外形或颜色分布。\n\n表面是由密集纤维形成的长绒材质，毛束有共同生长方向和细小分叉，轮廓处可见柔软的散边。通过不同部位的毛长、梳理方向与蓬松程度建立结构，而不是给一个光滑球体附上均匀噪点。绒毛高光由细纤维聚集形成，整体反射柔和，背光处可以透出薄薄的亮边；脸部和关节附近适当降低毛量，避免五官被毛团吞没。不要把长绒误画成编织线圈、针毡颗粒、皮肤汗毛或塑料尖刺。\n\n色彩作为角色设计的一部分固定下来，大片纯色与少量辅助色形成有辨识度的分区。毛色之间可以通过局部混纤柔和过渡，但分区边界必须随身体表面保持一致，不能随着转身滑动。环境颜色给角色留出呼吸空间，利用冷暖与明暗分离轮廓。光线允许出现局部亮区和较深阴影，让毛束有体积；避免全局过曝、每根纤维都闪亮或背景与主体使用同样密集的细节。\n\n环境按角色的玩偶尺度建立可信空间，地面、家具、植物或其他物件的大小关系保持一致。场景不必都是微缩玩具，但应选择能衬托柔软材质的表面，例如平整硬地、略粗糙的墙面或适量自然材料。近处纹理负责建立尺度，远处重复形体负责表达深度；角色经过时产生正确遮挡和接触阴影。利用留白与清楚的行进区域组织构图，不让背景道具遮断关键表情或肢体。\n\n动态遵循柔软填充物的惯性。躯干先发生重心变化，四肢承担支撑或推进，腹部、脸颊和绒毛再出现幅度较小的跟随运动；落地时有轻微压缩，恢复时有阻尼，不能像果冻一样持续震荡。行走时左右支撑关系交替成立，步幅、身体起伏和手臂摆动相互配合；停止、转向或受到触碰时，保留力从接触点传向身体的先后顺序。表情变化要有准备和回落，保持眼神的目标与注意力连贯。\n\n镜头根据内容选择靠近、观察、跟随或切换视角，运动速度服务于表演，不必始终追着主体前进。需要追随时让景物视差与角色实际位移一致；需要特写时关注毛束受压、细小表情和手部接触，而不是突然把身体拉伸填满画面。跨镜头维持角色的轮廓、色块位置、绒毛方向与五官间距，跨帧保持脚底接触、道具握持和光线方向。纤维允许随动作轻摆，却不能不断生成或消失；不要把材质变化误当表演，也不要在同一作品中突然切换成写实动物、硬质公仔或布料贴图的人体。",
