    "bestFor": "图形叙事、文学片头、城市诗意短片、印刷艺术风格广告",
    "promptTemplate": "采用整段一致的套色木刻版画视觉语言，把当前创作内容重新组织成有雕刻痕迹的线与块面。所有人物、物件和环境先建立明确剪影，再用粗细有层次的黑色轮廓、成组排线与留白说明内部结构。外轮廓要有刀刻般的力量和轻微不规则，细线围绕体积方向排列，不能变成覆盖所有表面的装饰网格。人物保留可辨认的姿态与情绪，但不绘制照片式毛孔、透明皮肤或无穷细节。\n\n画面像少量色版压印在有质地的纸上。为当前内容选定有限的主色、辅助色和纸色，先确定大面积明暗关系，再把必要信息分配给各色版。色块边缘可以有克制的套印偏移与吃墨不均，偏移尺度在整部作品中保持一致；不要让每个物体都套用同一种彩色光晕。纸面颗粒属于承载画面的底层，随镜头与画面关系稳定存在，不能像数字噪声一样每帧跳变或覆盖主体眼睛。\n\n材质主要通过刀法和墨色解释。硬表面可以使用较直、间距稳定的刻线，柔软织物使用顺着褶皱转折的弧线，自然物使用有组织的短刻痕和不完全规则的边缘。明暗通过线条密度、色块面积与留白决定，不依赖写实的镜面反射和渐变塑形。高光像预先留下的纸色或浅色版，阴影形成可阅读的整体块面；同一种材料在不同镜头中沿用同一组线条规则。\n\n空间保留足够透视，让前景、中景、远景和动作路径清楚，但主动压缩照片中的细碎层次。把建筑、地形或室内结构归纳为相互遮挡的大平面，用尺度递减、明度差和轮廓疏密建立纵深。前景的黑色结构可以帮助框定画面，远景线条相应减少，重要主体周围留出明确负空间。环境不能随着角色移动而重新排版，消失点、地平线和物体相对位置需要持续成立。\n\n动态应让静态版画语言真正参与表演。角色动作由可读的关键姿势连接，衣物和附属物跟随重心变化形成有节奏的轮廓；轮廓改变时，内部排线仍附着在对应表面，不能像一层纹理滑过身体。水、风、烟或雨若在内容中出现，将其转换成少量方向明确、节奏不同的刻线和色片，运动方向受环境条件约束。允许边缘出现细微的手工线条变化，但变化不能破坏形体，不要用整画面闪烁或频繁重画冒充生命感。\n\n镜头与剪辑按创作内容自由组织，保持版画构图对平衡、疏密和视觉重心的要求。移动机位时让透视和遮挡自然变化，同时保持有限色版与刀刻线条的表现方式；切换到近景时增加与叙事有关的结构，避免突然生出写实细节。跨帧和跨镜头锁定角色外形、服饰分区、色板、墨色密度及纸面尺度，动作衔接保持方向、视线和物件状态连续。整部作品始终维持套色木刻，不在行进中变成照片、油画、彩窗或铅笔素描；参考只提供视觉分析依据，不复刻其中人物、服装、街道构图或情节。",
